function modal(title,body,handler,submit='Save'){dialog.classList.remove('wide-dialog','row-inspector','column-inspector','formula-drawer','rules-drawer');dialog.innerHTML=`<form id="modal-form"><div class="modal-head"><h2>${esc(title)}</h2><button type="button" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">${esc(submit)}</button></div></form>`;submitHandler=handler;if(dialog.open)dialog.close();dialog.showModal();}
dialog.addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{const ok=await submitHandler(f);if(ok!==false)dialog.close();}catch(e){toast(e.message);}});
let saveWorker=null;const workerCalls=new Map();
try{saveWorker=new Worker('/save-worker.js');saveWorker.addEventListener('message',e=>{const done=workerCalls.get(e.data.id);workerCalls.delete(e.data.id);done?.(e.data);});saveWorker.addEventListener('error',()=>{saveWorker=null;for(const [id,done] of workerCalls){workerCalls.delete(id);done({ok:false,status:0,text:JSON.stringify({error:'The save worker stopped. Your change was not saved; please retry.'})});}});}catch{saveWorker=null;}
// The workspace is cloned synchronously by postMessage at call time, so later local edits cannot leak into this request.
async function workerRequest(url,body){const id=uid();const res=await new Promise(resolve=>{workerCalls.set(id,resolve);saveWorker.postMessage({id,url:new URL(url,location.href).href,body,headers:{'Content-Type':'application/json','X-Sheets-Tester':testerName,'X-Sheets-Client':clientId}});});let x;try{x=JSON.parse(res.text);}catch{x={error:'Unexpected server response ('+res.status+')'};}if(!res.ok){const error=Error(x.error||'Save failed');error.status=res.status;throw error;}return x;}
async function request(url,body){if(url==='/api/state'&&saveWorker)return workerRequest(url,body);const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-Sheets-Tester':testerName,'X-Sheets-Client':clientId},body:JSON.stringify(body)});const x=await r.json();if(!r.ok){const error=Error(x.error);error.status=r.status;throw error;}return x;}

// Captures the focused editor/cell so a re-render (optimistic or confirmed) does not interrupt typing or navigation.
function renderPreservingFocus(){const active=document.activeElement;const focus=active?.classList.contains('cell-input')?{row:active.dataset.row,col:active.dataset.col,value:active.value,start:active.selectionStart,end:active.selectionEnd,type:active.type,editing:active.dataset.editing,cancelValue:active.dataset.cancelValue,dirty:active.value!==(active.dataset.editStart??active.dataset.raw??active.value)}:null;const gridFocus=!focus&&!!active?.closest?.('td[data-grid-row]');render();if(focus){const editor=document.querySelector(`.cell-input[data-row="${CSS.escape(focus.row)}"][data-col="${CSS.escape(focus.col)}"]`);if(editor){editor.focus();if(focus.editing){editor.dataset.editing=focus.editing;editor.dataset.cancelValue=focus.cancelValue??'';}if(focus.dirty&&focus.type!=='checkbox'&&editor.matches('input,textarea')){editor.value=focus.value;if(focus.start!==null)try{editor.setSelectionRange(focus.start,focus.end);}catch{}}}}else if(gridFocus&&!dialog.open)restoreGridFocus();}
let pendingSaves=0;
function setSaveStatus(){const el=$('#save-status');if(!el)return;el.classList.toggle('busy',pendingSaves>0);el.lastChild&&(el.lastChild.textContent=pendingSaves>0?' Saving…':' All changes saved');}
// Optimistic editing (see edit-queue.mjs): the grid shows confirmed state + queued edits immediately; saves stay
// serialized and are rebuilt on the newest server-confirmed state; rejected saves drop out of the display.
editQueue=createEditQueue({getState:()=>state,setState:v=>{state=v;},
 // Sends only the changed fields. The server answers with its own field-level changes (metadata, activity,
 // automation results), applied to the confirmed state; if it merged with another tab's newer save it returns the full state.
 send:async(next,label,base)=>{const patch=diffState(base,next);if(isEmptyPatch(patch))return base;saving=true;setSaveStatus();try{const x=await request('/api/patch',{revision,label,patch});revision=x.revision;remoteChanged=false;conflictDraft=null;if(x.merged)toast('Saved and merged with changes from another tab');if(x.state)return x.state;try{return applyPatch(base,x.patch);}catch{const r=await fetch('/api/state');const fresh=await r.json();revision=fresh.revision;return fresh.state;}}finally{saving=false;}},
 onChange:()=>{pendingSaves=editQueue.pending;renderPreservingFocus();setSaveStatus();},
 onConflict:next=>{conflictDraft=next;notifyRemoteChange();},onError:e=>toast(e.message)});
function mutate(label,fn){if(conflictDraft){toast('Resolve the workspace conflict before saving another change.');return Promise.resolve(false);}return editQueue.mutate(label,fn);}
window.addEventListener('beforeunload',e=>{if(pendingSaves>0||conflictDraft){e.preventDefault();e.returnValue='';}});

function blankRow(s,cells={}){return {id:uid(),parentId:null,cells:Object.fromEntries(s.columns.map(c=>[c.id,cells[c.id]??(c.type==='checkbox'?false:'')])),comments:[],attachments:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};}
// Memoized per render: render() rebuilds `calc`, so any state change invalidates the memo.
let visibleMemo=null;
function visibleRows(s){
 const filterId=localStorage.getItem('sheets-filter-'+s.id),key=[s.id,query,statusFilter,filterId,collapsed.size?[...collapsed].join(','):''].join('\u0001');
 if(visibleMemo&&visibleMemo.state===state&&visibleMemo.calc===calc&&visibleMemo.s===s&&visibleMemo.key===key)return visibleMemo.rows;
 const rows=computeVisibleRows(s,filterId);visibleMemo={state,calc,s,key,rows};return rows;
}
function computeVisibleRows(s,filterId){
 const rowMap=new Map(s.rows.map(r=>[r.id,r]));
 const filter=(s.savedFilters||[]).find(f=>f.id===filterId);const sc=colBy(s,'Status'),needle=query.toLowerCase();
 let rows=s.rows.filter(r=>{if(query&&!s.columns.some(c=>String(val(s,r,c)).toLowerCase().includes(needle)))return false;if(statusFilter&&String(val(s,r,sc))!==statusFilter)return false;return !filter||matchesConditions(s,r,filter.conditions,filter.match,val);});
 if(filter?.includeParents){const ids=new Set(rows.map(r=>r.id));for(const row of rows){let p=row.parentId;while(p){ids.add(p);p=rowMap.get(p)?.parentId;}}rows=s.rows.filter(r=>ids.has(r.id));}
 if(collapsed.size&&!query&&!statusFilter&&!filter)rows=rows.filter(r=>{let p=r.parentId;while(p){if(collapsed.has(p))return false;p=rowMap.get(p)?.parentId;}return true;});
 return sortRows(s,rows,s.sorts||[],val);
}
function sheetPage(){const s=sheet();if(!s)return empty('A fresh start','Create your first sheet to organize your work.','Create sheet','new-sheet');const rows=visibleRows(s),sc=colBy(s,'Status');return `<section class="sheet-heading"><div><div class="eyebrow">WORKSPACE SHEET</div><h1>${esc(s.name)} ${button('···','sheet-settings','aria-label="Sheet settings"','more')}</h1><p>${esc(sheetDescription(s))}</p></div><div class="heading-actions">${s.budgetAudit?button('Import review','budget-review'):""}${button(icon('download',15)+' Export','export-menu')}${button(icon('plus',15)+' Add row','add-row','','primary')}</div></section><div class="sheet-commandbar" aria-label="Sheet toolbar"><select id="sheet-view-picker" aria-label="Sheet view">${['Table','Board','Calendar','Gantt','Timeline','Dashboard'].map(v=>option(v,v==='Table'?'Grid':v,v===view)).join('')}</select>${button(icon('undo',16),'undo','title="Undo last change (⌘Z / Ctrl+Z)" aria-label="Undo sheet change"')}${button(icon('redo',16),'redo','title="Redo last change (⌘Y / Ctrl+Y)" aria-label="Redo sheet change"')}<details class="command-search"><summary aria-label="Find in sheet" title="Find in sheet">${icon('search',17)}</summary><div class="command-popover"><input id="search" value="${esc(query)}" placeholder="Find in this sheet…" aria-label="Search sheet">${button('Find and replace… (⌘⇧H)','find-replace','','find-replace-link')}</div></details>${button(icon('filter',17)+'Filter','sheet-filter')}${button(icon('sort',17)+'Sort','sort')}${button(icon('columns',17)+'Columns','columns-manager')}<span class="command-divider"></span><details class="command-format"><summary>${icon('format',17)}Format <span>⌄</span></summary><div class="command-popover">${sheetToolbar(s)}</div></details>${button(icon('rules',17)+'Format rules','format-rules')}${button('ƒx Formulas','formula-editor')}${button(rowIcon('comment')+'Comments','row-comments','title="Row comments, files, proofs and history" aria-label="Open row panel"')}${button(icon('summary',17)+'Summary','sheet-summary')}<span class="tab-spacer"></span><details class="command-more"><summary>More tools <span>⌄</span></summary><div class="command-popover">${sheetMenus(s)}${button('View options','view-options')}${button('Automations','sheet-automations')}${button('Requests','sheet-requests')}${button('Keyboard shortcuts','keyboard-help')}</div></details></div>${view==='Table'?grid(s,rows):view==='Board'?board(s,rows):view==='Calendar'?calendar(s,rows):view==='Dashboard'?dashboard(s):timeline(s,rows)}<div class="sheet-footer"><span id="grid-selection-status" role="status"></span><span><span class="live-dot"></span> ${rows.length} visible rows</span><span>${view==='Table'?'Drag or Shift-click to select cells · ⌘C / ⌘V · Right-click for row actions':'All views use the same sheet data'}</span></div>`;}
let gridKey='';
// ---- Virtualized grid body: a sliding window of rows with spacer rows above and below. ----
const GRID_WINDOW=120;let gridStart=0,gridPrintAll=false,gridMetaMemo=null,gridScrollRaf=0,gridHeightsKey='';const gridHeights=createHeightIndex(29);
function gridMeta(s){if(gridMetaMemo?.s===s&&gridMetaMemo.state===state&&gridMetaMemo.n===s.rows.length)return gridMetaMemo;const index=new Map(s.rows.map((r,i)=>[r.id,i])),byId=new Map(s.rows.map(r=>[r.id,r])),parents=new Set(),dc=new Map();for(const r of s.rows)if(r.parentId)parents.add(r.parentId);const depth=r=>{let d=dc.get(r.id);if(d!==undefined)return d;d=0;let p=r.parentId;while(p&&d<20){d++;p=byId.get(p)?.parentId;}dc.set(r.id,d);return d;};return gridMetaMemo={s,state,n:s.rows.length,index,parents,depth};}
function gridRowHTML(s,r,cols,gm){return `<tr class="${selected.has(r.id)?'row-selected':''} ${r.locked?'row-locked':''}"><td class="row-select"><input class="row-check" data-row="${r.id}" type="checkbox" aria-label="Select ${esc(title(s,r))}" ${selected.has(r.id)?'checked':''}></td><td class="row-num">${button(String((gm.index.get(r.id)+1)),'row-options',`data-id="${r.id}" aria-label="Row ${(gm.index.get(r.id)+1)} options" title="Row actions · drag to move" draggable="true"`,'row-number-button')}</td><td class="row-tools-cell">${rowTools(s,r)}</td>${cols.map((c,i)=>`<td tabindex="-1" data-grid-row="${r.id}" data-grid-col="${c.id}" style="${gridFrozen.has(c.id)?'left:'+gridFrozen.get(c.id)+'px;':''}${styleText(cellFormat(s,r,c,val))}" class="cell ${c.formula?'calculated':''} ${gridFrozen.has(c.id)?'frozen':''} ${gridFrozenEdge===c.id?'frozen-edge':''}" ${c.type==='select'?`data-tone="${color(String(val(s,r,c)))}"`:''}><div class="cell-inner" style="${i===0?`padding-left:${gm.depth(r)*18+5}px`:''}">${i===0&&gm.parents.has(r.id)?button(collapsed.has(r.id)?'▸':'▾','collapse',`data-id="${r.id}" aria-label="Toggle children"`,'collapse'):''}${editor(s,r,c)}${/^https?:\/\//i.test(r.cellLinks?.[c.id]||'')?`<a class="cell-hyperlink" href="${esc(r.cellLinks[c.id])}" target="_blank" rel="noopener noreferrer" aria-label="Open cell hyperlink">↗</a>`:''}</div></td>`).join('')}<td class="row-detail">${button('↗','row-detail',`data-id="${r.id}" aria-label="Open row details"`,'row-open')}${r.comments?.length?'<span class="comment-dot"></span>':''}</td></tr>`;}
function gridBodyHTML(s,rows,cols){const key=s.id+'|'+sheetWrap;if(key!==gridHeightsKey){gridHeightsKey=key;gridHeights.clear();}const n=rows.length,W=gridPrintAll?n:GRID_WINDOW;if(gridPrintAll)gridStart=0;gridStart=Math.max(0,Math.min(gridStart,Math.max(0,n-W)));const end=Math.min(n,gridStart+W),gm=gridMeta(s);const spacer=(px,cls)=>px>0?`<tr class="grid-spacer ${cls}" aria-hidden="true"><td colspan="${cols.length+4}" style="height:${Math.round(px)}px"></td></tr>`:'';return spacer(gridHeights.top(rows,gridStart),'top')+rows.slice(gridStart,end).map(r=>gridRowHTML(s,r,cols,gm)).join('')+spacer(gridHeights.total(rows)-gridHeights.top(rows,end),'bottom');}
// Measures rendered rows (in the table's own CSS pixels) so spacer heights track wrap and density.
function measureGridRows(){const tbody=document.querySelector('table.grid tbody');if(!tbody||gridPrintAll)return;let changed=false;for(const tr of tbody.children){if(tr.classList.contains('grid-spacer'))continue;const id=tr.querySelector('.row-check')?.dataset.row;if(id&&gridHeights.set(id,tr.offsetHeight))changed=true;}gridHeights.freeze();if(!changed)return;const rows=visibleRows(sheet()),end=Math.min(rows.length,gridStart+GRID_WINDOW);const top=tbody.querySelector('.grid-spacer.top td'),bottom=tbody.querySelector('.grid-spacer.bottom td');if(top){const before=top.offsetHeight,px=Math.round(gridHeights.top(rows,gridStart));top.style.height=px+'px';const sc=tbody.closest('.grid-scroll');if(sc&&px!==before&&gridStart>0)sc.scrollTop+=(px-before)*(gridScale(tbody)||1);}if(bottom)bottom.style.height=Math.round(gridHeights.total(rows)-gridHeights.top(rows,end))+'px';}
function gridScale(tbody){const css=tbody.offsetHeight;return css?tbody.getBoundingClientRect().height/css:1;}
function updateGridRangeLabel(first,count,total){const el=$('#grid-range-label');if(el)el.textContent=total?`Rows ${(first+1).toLocaleString()}–${Math.min(total,first+count).toLocaleString()} of ${total.toLocaleString()}`:'No rows';}
function replaceGridBody(s,rows){const tbody=document.querySelector('table.grid tbody');if(!tbody)return render();const hadFocus=tbody.contains(document.activeElement);tbody.innerHTML=gridBodyHTML(s,rows,s.columns.filter(c=>!c.hidden));paintRange();measureGridRows();if(hadFocus){const td=activeCell&&tbody.querySelector(`td[data-grid-row="${CSS.escape(activeCell.rowId)}"][data-grid-col="${CSS.escape(activeCell.colId)}"]`);(td||tbody.closest('table')).focus({preventScroll:true});}}
// Ensures visible-row index `i` is rendered; returns true when the body was replaced.
function ensureRowRendered(i,rows){if(i>=gridStart&&i<gridStart+GRID_WINDOW)return false;gridStart=Math.max(0,i-40);replaceGridBody(sheet(),rows);return true;}
function syncGridWindow(scroller){const s=sheet();if(!s||page!=='sheet'||view!=='Table'||gridPrintAll)return;const tbody=scroller.querySelector('table.grid tbody');if(!tbody)return;const ed=document.activeElement;if(ed?.dataset?.editing==='true'&&tbody.contains(ed))return;const rows=visibleRows(s),scale=gridScale(tbody)||1,head=scroller.querySelector('thead')?.getBoundingClientRect().height||0,y=Math.max(0,scroller.scrollTop-head)/scale;const first=gridHeights.indexAt(rows,y),count=Math.max(1,gridHeights.indexAt(rows,y+scroller.clientHeight/scale)-first+1);updateGridRangeLabel(first,count,rows.length);if(first>=gridStart+15&&first+count<=gridStart+GRID_WINDOW-15)return;const start=Math.max(0,Math.min(first-40,rows.length-GRID_WINDOW));if(start===gridStart)return;gridStart=start;replaceGridBody(s,rows);}
document.addEventListener('scroll',e=>{const t=e.target;if(!t?.classList?.contains('grid-scroll')||gridScrollRaf)return;gridScrollRaf=requestAnimationFrame(()=>{gridScrollRaf=0;syncGridWindow(t);});},true);
function grid(s,rows){const key=s.id+query+statusFilter+localStorage.getItem('sheets-filter-'+s.id);if(key!==gridKey){gridStart=0;gridKey=key;}computeFrozen(s);const cols=s.columns.filter(c=>!c.hidden);return `<div class="grid-scroll ${sheetWrap?'wrap-enabled':'wrap-clipped'}"><table class="grid" tabindex="-1" style="zoom:${sheetZoom/100};width:${cols.reduce((n,c)=>n+(c.width||150),0)+202}px"><thead><tr><th class="row-select add-column-corner">${button(icon('plus',16),'add-column-start','aria-label="Add new column" title="Add new column" aria-haspopup="dialog"','add-column-button')}</th><th class="row-num"><input type="checkbox" id="select-all" aria-label="Select all visible rows" title="Select all rows" ${rows.length&&rows.every(r=>selected.has(r.id))?'checked':''}></th><th class="row-tools-head" aria-label="Row tools"><span title="Attachments">${rowIcon('attachment')}</span><span title="Comments">${rowIcon('comment')}</span><span title="Proofing and review">${rowIcon('proof')}</span><span title="Row lock">${rowIcon('lock')}</span></th>${cols.map(c=>`<th data-grid-col="${c.id}" class="${gridFrozen.has(c.id)?'frozen':''} ${gridFrozenEdge===c.id?'frozen-edge':''}" style="width:${c.width||150}px;min-width:${c.width||150}px;${gridFrozen.has(c.id)?'left:'+gridFrozen.get(c.id)+'px;':''}${styleText(c.sourceHeaderFormat||{})}"><button data-action="select-column" data-id="${c.id}" draggable="${s.columns[0].id===c.id?'false':'true'}" aria-label="Select column ${esc(c.name)}"><span class="column-icon" title="${esc(typeLabel(c))}" aria-hidden="true">${esc(typeGlyph(c))}</span><span class="column-label">${esc(c.name)}</span> ${c.formula?'<span class="fx">ƒx</span>':''}</button><button class="column-menu-trigger" data-action="column-menu" data-id="${c.id}" aria-label="Column options for ${esc(c.name)}" aria-haspopup="menu">⋯</button><span class="column-resizer" data-col="${c.id}" role="slider" tabindex="0" aria-label="Resize ${esc(c.name)}" aria-valuemin="70" aria-valuemax="800" aria-valuenow="${c.width||150}" title="Drag to resize column"></span></th>`).join('')}<th class="row-detail"></th></tr></thead><tbody>${gridBodyHTML(s,rows,cols)}</tbody></table>${rows.length?'':`<div class="empty-inline">No rows match this view.</div>`}<button class="add-row-bottom" data-action="add-row">＋ Add a row</button></div><div class="grid-pagination"><div class="grid-display-controls">${button('↵ Wrap text','toggle-grid-wrap',`aria-pressed="${sheetWrap}" title="Wrap text in the sheet"`)}<span class="zoom-controls">${button('−','grid-zoom-out',`aria-label="Zoom out" ${sheetZoom<=50?'disabled':''}`)}<select id="grid-zoom" aria-label="Sheet zoom">${[50,60,70,80,90,100,110,120,130,140,150].map(z=>option(z,z+'%',z===sheetZoom)).join('')}</select>${button('+','grid-zoom-in',`aria-label="Zoom in" ${sheetZoom>=150?'disabled':''}`)}</span></div><label class="row-jump">Go to row <input id="grid-row-jump" type="number" min="1" max="${s.rows.length||1}" placeholder="#" aria-label="Go to row number (⌘G)"></label><span id="grid-range-label" aria-live="polite">${rows.length?`Rows ${(gridStart+1).toLocaleString()}–${Math.min(rows.length,gridStart+GRID_WINDOW).toLocaleString()} rendered of ${rows.length.toLocaleString()}`:"No rows"}</span></div>`;}
function editor(s,r,c){const v=val(s,r,c),attrs=`data-row="${r.id}" data-col="${c.id}" aria-label="${esc(c.name)} for ${esc(title(s,r))}"`;
 if(c.type==='files')return button(rowIcon('attachment')+' '+(r.attachments?.length||0),'row-panel',`data-id="${r.id}" data-tab="attachments"`,'rich-cell');
 if(r.locked&&c.type==='checkbox')return `<input type="checkbox" class="checkbox" disabled ${v?'checked':''} aria-label="${esc(c.name)} · locked">`;
 if(isReadOnly(c)||r.locked)return `<span class="formula-value ${String(v).startsWith('#')?'error-value':''}" title="${esc(r.locked?'Locked row':c.formula||'Automatic value')}">${esc(displayCell(v,c))||'—'}</span>`;
 if(typeof r.cells[c.id]==='string'&&r.cells[c.id].startsWith('='))return `<input class="cell-input" ${attrs} type="text" value="${esc(displayCell(v,c))}" data-raw="${esc(r.cells[c.id])}">`;
 if(c.type==='vote')return button('↑ '+(Array.isArray(r.cells[c.id])?r.cells[c.id].length:0),'vote-cell',`${attrs} aria-pressed="${(r.cells[c.id]||[]).includes(testerName)}"`,'rich-cell');
 if(c.type==='timeTracking')return `<span class="time-elapsed" data-seconds="${r.cells[c.id]?.totalSeconds||0}" data-running="${esc(r.cells[c.id]?.runningSince||'')}">${esc(displayCell(v,c))}</span>${button(r.cells[c.id]?.runningSince?'Pause':'Start','time-toggle',attrs,'rich-cell')}`;
 if(c.type==='worldClock')return `<span class="world-clock" data-zone="${esc(r.cells[c.id]||'UTC')}">${esc(v||'UTC')}</span>${button('Timezone','rich-cell',attrs,'rich-cell')}`;
 if(c.type==='color')return button(`<span class="color-chip" style="background:${/^#[0-9a-f]{6}$/i.test(v)?v:'#ffffff'}"></span>`+esc(v),'rich-cell',attrs,'rich-cell');
 if(c.type==='button'&&r.cells[c.id]?.url)return `<a class="row-link-button" href="${esc(r.cells[c.id].url)}" target="_blank" rel="noopener noreferrer">${esc(r.cells[c.id].label||'Open')}</a>${button('Edit','rich-cell',attrs,'rich-cell')}`;
 if(richTypes.includes(c.type))return button(esc(displayCell(v,c))||'<span class="muted">＋ Add</span>','rich-cell',attrs,'rich-cell');
 if(c.type==='checkbox')return `<input class="cell-input checkbox" type="checkbox" ${attrs} ${v===true?'checked':''}>`;
 if(['select','symbol'].includes(c.type))return `<select class="cell-input" ${attrs}>${option('','—')}${(c.options||[]).map(x=>option(x,x,x===v)).join('')}</select>`;
 if(!c.numericFormat&&(sheetWrap||cellFormat(s,r,c,val).wrap)&&['text','contact','email','phone'].includes(c.type))return `<textarea class="cell-input cell-wrap" rows="1" ${attrs} data-raw="${esc(r.cells[c.id]??'')}">${esc(v)}</textarea>`;
 return `<input class="cell-input" ${attrs} type="${c.type==='date'&&!String(r.cells[c.id]||'').startsWith('=')?'date':c.type==='datetime'&&!String(r.cells[c.id]||'').startsWith('=')?'datetime-local':'text'}" value="${esc(displayCell(v,c))}" data-value="${esc(v)}" data-raw="${esc(r.cells[c.id]??'')}" ${numericTypes.includes(c.type)?'inputmode="decimal"':''}>`;
}
function card(s,r){return `<article class="task-card" style="${styleText(cellFormat(s,r,s.columns[0],val))}" draggable="${!r.locked}" data-drag-row="${r.id}" data-action="row-detail" data-id="${r.id}" tabindex="0" role="button"><div class="card-top">${badge(val(s,r,colBy(s,'Priority')))}<span>···</span></div><h3>${esc(title(s,r))}</h3><p>${esc(val(s,r,colBy(s,'Owner'))||'Unassigned')}</p><div class="card-bottom"><span>▦ ${esc(val(s,r,colBy(s,'Due'))||'No due date')}</span><span>${r.comments?.length?'◌ '+r.comments.length:''}</span></div></article>`;}
function board(s,rows){const c=s.columns.find(c=>c.id===s.viewConfig?.boardColumnId)||colBy(s,'Status')||s.columns.find(c=>c.type==='select');if(!c)return empty('Give your work a flow','Add a dropdown column to organize cards into lanes.','Add column','new-column');const lanes=[...new Set([...(c.options||[]),...rows.map(r=>String(val(s,r,c))), ''])];return `<div class="board">${lanes.map(l=>{const rr=rows.filter(r=>String(val(s,r,c))===l);return `<section class="lane" data-lane="${esc(l)}" data-column="${c.id}"><div class="lane-head"><span class="lane-dot ${color(l)}"></span><h3>${esc(l||'Unassigned')}</h3><span>${rr.length}</span>${button('+','add-row',`data-lane="${esc(l)}" data-column="${c.id}" aria-label="Add card"`)}</div>${rr.map(r=>card(s,r)).join('')}</section>`;}).join('')}</div>`;}
function calendar(s,rows){const c=s.columns.find(c=>c.id===s.viewConfig?.dateColumnId)||colBy(s,'Due')||s.columns.find(c=>c.type==='date');if(!c)return empty('Put work on the calendar','Add a date column to see your schedule.','Add column','new-column');const start=new Date(month.getFullYear(),month.getMonth(),1),offset=start.getDay(),days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();return `<div class="calendar"><div class="calendar-nav"><h2>${month.toLocaleString(undefined,{month:'long',year:'numeric'})}</h2><div>${button('←','month-prev')}${button('Today','month-today')}${button('→','month-next')}</div></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="day-name">${d}</div>`).join('')}${Array.from({length:Math.ceil((offset+days)/7)*7},(_,i)=>{const n=i-offset+1,key=`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`;return `<div class="day ${n<1||n>days?'muted-day':''} ${key===today()?'today':''}">${n>0&&n<=days?`<span class="day-number">${n}</span>${rows.filter(r=>val(s,r,c)===key).map(r=>`<button class="calendar-event" style="${styleText(cellFormat(s,r,s.columns[0],val))}" data-action="row-detail" data-id="${r.id}">${esc(title(s,r))}</button>`).join('')}`:''}</div>`;}).join('')}</div></div>`;}
function timeline(s,rows){const timelineC=s.columns.find(c=>c.type==='timeline');const startC=s.columns.find(c=>c.id===s.viewConfig?.startColumnId)||colBy(s,'Start')||s.columns.find(c=>c.type==='date'),endC=s.columns.find(c=>c.id===s.viewConfig?.endColumnId)||colBy(s,'Due')||s.columns.filter(c=>c.type==='date')[1];if((!startC||!endC)&&timelineC)return timelineRanges(s,rows,timelineC);if(!startC||!endC)return empty('See the bigger picture','Add Start and Due date columns to build a timeline.','Add column','new-column');const rr=rows.filter(r=>val(s,r,startC)&&val(s,r,endC));const stamps=rr.flatMap(r=>[Date.parse(val(s,r,startC)),Date.parse(val(s,r,endC))]).filter(Number.isFinite);const min=stamps.length?Math.min(...stamps):Date.now(),max=stamps.length?Math.max(...stamps):min+14*864e5,span=Math.max(7,(max-min)/864e5+2);return `<div class="timeline"><div class="timeline-note">${view==='Gantt'?'Date-range Gantt':'Timeline'} · Edit dates in the table to reschedule. Dependency scheduling is on the roadmap.</div><div class="timeline-head"><span>Task</span><div>${Array.from({length:Math.min(10,Math.ceil(span))},(_,i)=>`<span>${new Date(min+i*span/Math.min(10,Math.ceil(span))*864e5).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span>`).join('')}</div></div>${rr.map(r=>{const a=Date.parse(val(s,r,startC)),b=Date.parse(val(s,r,endC));return `<div class="timeline-row"><button data-action="row-detail" data-id="${r.id}" style="padding-left:${depth(s,r)*16+16}px">${esc(title(s,r))}</button><div class="timeline-track"><button class="gantt-bar ${color(String(val(s,r,colBy(s,'Status'))))}" data-action="row-detail" data-id="${r.id}" style="${styleText(cellFormat(s,r,s.columns[0],val))};left:${(a-min)/864e5/span*100}%;width:${Math.max(1,(b-a)/864e5+1)/span*100}%" title="${esc(title(s,r))}: ${esc(val(s,r,startC))} – ${esc(val(s,r,endC))}">${esc(title(s,r))}</button></div></div>`;}).join('')}${rr.length?'':'<p class="empty-inline">Add dates to your rows to see them here.</p>'}</div>`;}
const metric=(label,value,note,cls='')=>`<article class="metric ${cls}"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`;
const empty=(title,body,label,action)=>`<section class="empty"><span class="empty-icon">▦</span><h2>${esc(title)}</h2><p>${esc(body)}</p>${button(label,action,'','primary')}</section>`;
function pageHeader(kicker,title,description,actions=''){return `<section class="sheet-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></section>`;}
function formsPage(){const ss=state.sheets.filter(s=>s.workspaceId===workspaceId);return pageHeader('LESS CHASING. MORE DOING.','Forms','Collect structured information directly into your sheets.',button('+ Create form','new-form','','primary'))+`<div class="page-body sheet-cards">${ss.flatMap(s=>(s.forms||[]).map(f=>`<article class="panel"><span class="eyebrow">${esc(s.name)}</span><h2>${esc(f.name)}</h2><p>${esc(f.description||'Add a new submission to this sheet.')}</p><div class="action-row">${button('Open form','open-form',`data-sheet="${s.id}" data-id="${f.id}"`,'primary')}${button('Edit','edit-form',`data-sheet="${s.id}" data-id="${f.id}"`)}${button('Delete','delete-form',`data-sheet="${s.id}" data-id="${f.id}"`)}</div><small>Local form · ${f.columnIds.length} fields</small></article>`)).join('')||empty('Turn requests into rows','Build a local intake form from your sheet columns.','Create form','new-form')}</div>`;}
function automationsPage(){return pageHeader('REPEAT WORK, HANDLED','Automations','Cell changes, new rows and dates can start local workflows.',button('+ New workflow','new-automation','','primary'))+`<div class="page-body">${currentSheets().map(s=>`<section class="panel automation"><span class="automation-icon">ϟ</span><div><h3>${esc(s.name)}</h3><p>${s.automations.length} workflow(s) · ${s.automations.filter(a=>a.enabled!==false).length} active</p></div>${button('Manage workflows','workspace-workflows',`data-id="${s.id}"`)}</section>`).join('')}<p class="hint">Date workflows run every minute while this local server runs. Requests and notifications stay in this app.</p></div>`;}
function activityPage(){return pageHeader('EVERY CHANGE HAS A STORY','Activity','A local history of changes across your workspaces.')+`<div class="page-body"><section class="panel">${[...(state.activity||[])].reverse().map(a=>`<div class="activity-row"><span class="activity-dot"></span><span>${esc(a.message)}</span><time>${esc(a.by||'Local')} · ${new Date(a.at).toLocaleString()}</time></div>`).join('')||'<p>Your activity will appear here as you work.</p>'}</section></div>`;}
async function editCell(el){const s=sheet(),r=s.rows.find(r=>r.id===el.dataset.row),c=s.columns.find(c=>c.id===el.dataset.col);if(!r||!c)return;if(r.locked||isReadOnly(c)){toast('Unlock the row before editing.');render();return;}try{const v=parseCell(c,el.type==='checkbox'?el.checked:el.value);validateCell(c,v);if(JSON.stringify(v)===JSON.stringify(r.cells[c.id]??'')){if(el.type!=='checkbox')el.value=displayCell(val(s,r,c),c);return;}if(el.dataset.submittedValue===JSON.stringify(v))return;el.dataset.submittedValue=JSON.stringify(v);await mutate(`Edited ${c.name} in ${s.name}`,n=>{n.sheets.find(x=>x.id===s.id).rows.find(x=>x.id===r.id).cells[c.id]=v;});}catch(e){toast(e.message);render();}}
function columnModal(existing,insertIndex){const s=sheet(),adding=!existing,type=existing?.type||'text',sections=typeSections(type),isPrimary=existing&&existing.id===s.columns[0].id;
 const section=(key,html)=>`<div class="column-section" data-section="${key}" ${sections.has(key)?'':'hidden'}>${html}</div>`;
 const typeSelect=`<label class="field">Column type<select name="type" id="column-type" ${isPrimary?'disabled':''}>${typeGroups.map(([group,types])=>`<optgroup label="${esc(group)}">${types.map(t=>option(t,columnTypes.find(([x])=>x===t)?.[1]||t,t===type)).join('')}</optgroup>`).join('')}</select></label>${isPrimary?'<input type="hidden" name="type" value="text">':''}`;
 const positionValue=String(insertIndex??defaultInsertIndex(s.columns,activeCell?.sheetId===s.id?activeCell.colId:''));
 const body=`<div class="column-editor-grid">${field('Column name','name',existing?.name||uniqueColumnName(s.columns),'text','required maxlength="80" id="column-name" autocomplete="off"')}${typeSelect}</div><p class="hint column-type-hint" id="column-type-hint" aria-live="polite">${esc(isPrimary?'The primary column holds row titles and hierarchy, so it stays text.':typeHints[type]||'')}</p>`
 +(adding?`<label class="field">Insert position<select name="position" id="column-position">${insertPositions(s.columns).map(o=>option(o.value,o.label,o.value===positionValue)).join('')}</select></label><p class="hint">New columns are inserted after the column you choose. The primary column always stays first.</p>`:'')
 +section('options',field('Dropdown choices (comma separated)','options',existing?.options?.join(', ')||'','text','placeholder="Not started, In progress, Complete"'))
 +section('formula',`<details class="column-more" ${existing?.formula?'open':''}><summary>Column formula</summary>${field('Formula applied to every row','formula',existing?.formula||'','text','placeholder="=[Quantity]@row * [Unit cost]@row" spellcheck="false"')}<p class="hint">Leave blank for values you type. Use the ƒx Formulas drawer for previews and references.</p></details>`)
 +section('numbering',`<div class="form-two">${field('Prefix','prefix',existing?.prefix||'')}${field('Minimum digits','digits',existing?.digits||1,'number','min="1" max="12"')}</div>`)
 +section('currency',selectField('Currency','currency',['USD','CAD','EUR','GBP','AUD'],existing?.currency||'USD'))
 +section('mirror',`${selectField('Connected-row source','connectionColumnId',[{value:'',label:'Choose a connected column'},...s.columns.filter(c=>c.type==='connected').map(c=>({value:c.id,label:c.name}))],existing?.connectionColumnId||'')}${field('Mirrored field name','mirrorColumn',existing?.mirrorColumn||'')}${selectField('Mirror calculation','mirrorAggregate',['join','sum','min','max','count'],existing?.mirrorAggregate||'join')}`)
 +section('progress',`<p class="hint">Checkboxes to track progress:</p>${s.columns.filter(c=>c.type==='checkbox').map(c=>`<label class="check-field"><input type="checkbox" name="progress-${c.id}" ${(existing?.progressColumnIds||[]).includes(c.id)?'checked':''}>${esc(c.name)}</label>`).join('')||'<p class="hint">Add a checkbox column first.</p>'}`)
 +`<details class="column-more"><summary>Width and display</summary>${field('Column width (pixels)','width',existing?.width||180,'number','min="80" max="600" step="10"')}</details>`
 +(existing&&!isPrimary?`<div class="action-row column-editor-actions">${button('Move left','move-column',`data-id="${existing.id}" data-direction="-1"`)}${button('Move right','move-column',`data-id="${existing.id}" data-direction="1"`)}${button('Delete column…','delete-column',`data-id="${existing.id}"`,'danger')}</div>`:'')
 +(existing?'<p class="hint">Changing the type validates every existing value first; nothing is converted if any value would be lost.</p>':'');
 modal(existing?'Column properties':'Add column',body,f=>{
 const c=buildColumn(f,s.columns,existing,uid);
 const converted=new Map();if(existing&&existing.type!==c.type){for(const r of s.rows){if(r.locked)throw Error('Unlock rows before converting columns.');let raw=r.cells[c.id]??'';if(raw&&typeof raw==='object'&&!richTypes.includes(c.type))raw=val(s,r,existing);const v=systemTypes.includes(c.type)?'':parseCell(c,raw);validateCell(c,v);converted.set(r.id,v);}}
 const at=adding?clampInsertIndex(s.columns,f.position):null;
 let renamed=0;return mutate(existing&&existing.name!==c.name?`Renamed column ${existing.name} to ${c.name}`:`${existing?'Updated':'Added'} column ${c.name}`,n=>{const sh=n.sheets.find(x=>x.id===s.id);if(existing&&existing.name!==c.name){renamed=applyColumnRename(n,s.id,existing.name,c.name);c.formula=renameColumnInFormula(c.formula,existing.name,c.name);}if(existing)sh.columns[sh.columns.findIndex(x=>x.id===existing.id)]=c;else sh.columns.splice(Math.min(at,sh.columns.length),0,c);for(const r of sh.rows)if(converted.has(r.id))r.cells[c.id]=converted.get(r.id);}).then(ok=>{if(ok&&renamed)toast(`Renamed · ${renamed} reference${renamed===1?'':'s'} updated in formulas and reports`);if(ok&&adding){toast('Added column '+c.name+' · Undo to remove');requestAnimationFrame(()=>{const th=document.querySelector(`th[data-grid-col="${CSS.escape(c.id)}"]`);th?.scrollIntoView({block:'nearest',inline:'nearest'});th?.querySelector('button')?.focus();});}return ok;});
 },existing?'Save column':'Add column');dialog.classList.add('column-inspector');const name=$('#column-name');if(adding&&name){name.focus();name.select();}}
function rowModal(id){const s=sheet(),r=s.rows.find(r=>r.id===id);modal(title(s,r),`${r.locked?'<p class="locked-note">🔒 This row is locked. Comments and files remain available.</p>':''}<div class="detail-fields">${s.columns.filter(c=>!c.hidden).map(c=>cellField(s,r,c,c.id)).join('')}</div><hr><h3>Conversation</h3>${reviewNotes(r.comments)}${commentComposer()}<h3>Attachments</h3>${r.attachments.map(a=>`<div class="attachment"><span>${esc(a.name)}</span>${button('Download','download-attachment',`data-row="${r.id}" data-id="${a.id}"`)}</div>`).join('')}<label class="field">Attach a file (up to 2 MB)<input type="file" id="attachment-input"></label>`,async f=>{const file=$('#attachment-input').files[0],attachment=file?await readLocalFile(file):null;const cells={};if(!r.locked)for(const c of s.columns.filter(c=>!c.hidden&&!isReadOnly(c))){cells[c.id]=readCellField(c,c.id,f,r.cells[c.id]);validateCell(c,cells[c.id]);}return mutate(`Updated row in ${s.name}`,n=>{const rr=n.sheets.find(x=>x.id===s.id).rows.find(x=>x.id===r.id);Object.assign(rr.cells,cells);if(f.comment?.trim())rr.comments.push({id:uid(),text:f.comment.trim(),by:testerName,at:new Date().toISOString()});if(attachment)rr.attachments.push(attachment);});});}
function download(name,data,type='text/plain'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function parseCSV(text){let rows=[],row=[],v='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(v);v='';}else if(ch==='\n'&&!quoted){row.push(v.replace(/\r$/,''));rows.push(row);row=[];v='';}else v+=ch;}if(quoted)throw Error('Unclosed CSV quote');if(v||row.length){row.push(v.replace(/\r$/,''));rows.push(row);}return rows;}
function importModal(){modal('Import data',selectField('Import type','kind',[{value:'excel',label:'Excel workbook / export ZIP → new workspace'},{value:'bundle',label:'Excel export bundle → add workspace'}, {value:'csv',label:'CSV → new sheet'},{value:'json',label:'Project backup → replace local project'}],'csv')+'<label class="field">File<input id="import-file" type="file" accept=".csv,.json,.xlsx,.zip" required></label><p class="hint">Convert Excel exports with scripts/import_excel.py, then select the generated excel-import.json bundle to add a workspace. CSV imports values as text. Project restore replaces all local workspaces and can be undone.</p>',async f=>{const file=$('#import-file').files[0];if(!file)return false;if(f.kind==='excel'){const bytes=new Uint8Array(await file.arrayBuffer());if(bytes.length>16*1024*1024)throw Error('Upload exceeds 16 MB');let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const result=await serverChange('/api/import-excel',{fileName:file.name,base64:btoa(binary)});workspaceId=result.importedWorkspaceId;page='home';render();toast(result.report.length+' workbooks converted and imported');return true;}const text=await file.text();if(f.kind==='bundle'){const bundle=JSON.parse(text);if(!bundle.workspace?.id||!Array.isArray(bundle.sheets))throw Error('Choose a converted Excel export bundle.');if(state.workspaces.some(w=>w.id===bundle.workspace.id))throw Error('This bundle is already imported.');const ok=await mutate('Imported Excel workspace',n=>{n.workspaces.push(bundle.workspace);n.sheets.push(...bundle.sheets);});if(ok){workspaceId=bundle.workspace.id;sheetId=bundle.sheets[0]?.id;page='home';render();}return ok;}if(f.kind==='json'){const imported=JSON.parse(text);return mutate('Restored project backup',n=>Object.assign(n,imported.state||imported));}const [headers,...rows]=parseCSV(text);if(!headers?.length)throw Error('CSV has no columns');const names=new Set();const columns=headers.map((h,i)=>{let name=h.trim()||`Column ${i+1}`;while(names.has(name))name+=' (2)';names.add(name);return {id:uid(),name,type:'text',options:[],formula:''};});const sh={id:uid(),workspaceId,folderId:null,name:file.name.replace(/\.csv$/i,''),description:'Imported from CSV',columns,rows:[],automations:[],forms:[],createdAt:new Date().toISOString()};sh.rows=rows.filter(a=>a.some(v=>v!=='')).map(a=>blankRow(sh,Object.fromEntries(columns.map((c,i)=>[c.id,a[i]??'']))));const ok=await mutate('Imported CSV',n=>n.sheets.push(sh));if(ok){sheetId=sh.id;page='sheet';view='Table';render();}return ok;},'Import');}
