 close:()=>dialog.close(),sheet:el=>{sheetId=el.dataset.id;const target=sheet();if(!target)return toast('Sheet no longer exists.');workspaceId=target.workspaceId;page='sheet';query='';statusFilter='';sortCol='';selected.clear();render();},page:el=>{page=el.dataset.page;render();},view:el=>{view=el.dataset.view;render();},
