 'workspace-settings':()=>modal('Workspace settings',field('Name','name',state.workspaces.find(w=>w.id===workspaceId)?.name,'text','required'),f=>mutate('Renamed workspace',n=>n.workspaces.find(w=>w.id===workspaceId).name=f.name)),
