 'delete-folder':async el=>{await mutate('Deleted folder',n=>{n.folders=n.folders.filter(f=>f.id!==el.dataset.id);n.sheets.forEach(s=>{if(s.folderId===el.dataset.id)s.folderId=null;});});dialog.close();},
 'new-sheet':()=>modal('Create a sheet',field('Sheet name','name','','text','required placeholder="e.g. Project tracker"')+selectField('Start with','template',['Project tracker','Blank sheet'],'Project tracker')+selectField('Folder','folder',[{value:'',label:'Workspace root'},...state.folders.filter(f=>f.workspaceId===workspaceId).map(f=>({value:f.id,label:f.name}))],''),async f=>{const columns=(f.template==='Blank sheet'?[['Name','text']]:[['Task','text'],['Status','select'],['Owner','contact'],['Start','date'],['Due','date'],['Priority','select']]).map(([name,type])=>({id:uid(),name,type,width:name==='Task'||name==='Name'?300:160,options:name==='Status'?['Not started','In progress','In review','Complete']:name==='Priority'?['Low','Medium','High']:[],formula:''}));const sh={id:uid(),workspaceId,folderId:f.folder||null,name:f.name,description:'',columns,rows:[],automations:[],forms:[],createdAt:new Date().toISOString()};const ok=await mutate('Created '+f.name,n=>n.sheets.push(sh));if(ok){sheetId=sh.id;page='sheet';view='Table';render();}return ok;},'Create sheet'),
 'sheet-settings':()=>{const s=sheet();modal('Sheet settings',field('Name','name',s.name,'text','required')+field('Description','description',s.description)+selectField('Folder','folder',[{value:'',label:'Workspace root'},...state.folders.filter(f=>f.workspaceId===workspaceId).map(f=>({value:f.id,label:f.name}))],s.folderId||'')+button('Delete sheet','delete-sheet','','danger'),f=>{const name=f.name.trim();if(!name)throw Error('Enter a sheet name.');if(name!==s.name&&state.sheets.some(x=>x.id!==s.id&&x.name.toLowerCase()===name.toLowerCase()))throw Error('Another sheet already uses that name; cross-sheet formulas need unique names.');let updated=0;return mutate(name!==s.name?'Renamed sheet '+s.name+' to '+name:'Updated sheet settings',n=>{if(name!==s.name)updated=applySheetRename(n,s.name,name);Object.assign(n.sheets.find(x=>x.id===s.id),{name,description:f.description,folderId:f.folder||null});}).then(ok=>{if(ok&&updated)toast(`Renamed · ${updated} formula reference${updated===1?'':'s'} updated`);return ok;});});},
 'delete-sheet':()=>{const s=sheet();modal('Delete sheet',`<p>Delete <strong>${esc(s.name)}</strong> and its rows? You can undo this locally.</p>`,()=>mutate('Deleted '+s.name,n=>{n.sheets=n.sheets.filter(x=>x.id!==s.id);n.reports.forEach(r=>r.sheetIds=r.sheetIds.filter(x=>x!==s.id));(n.dashboards||[]).forEach(d=>d.sheetIds=d.sheetIds.filter(x=>x!==s.id));}),'Delete sheet');},
