 'export-menu':()=>{const cur=sheet(),folderSheets=cur.folderId?state.sheets.filter(x=>x.folderId===cur.folderId):[];modal('Export your work',selectField('Format','format',[{value:'xlsx',label:'Current sheet · Excel (.xlsx) with formulas'},...(folderSheets.length>1?[{value:'xlsx-folder',label:`This folder (${folderSheets.length} sheets) · Excel workbook`}]:[]),{value:'xlsx-workspace',label:`Workspace (${currentSheets().length} sheets) · Excel workbook`},{value:'csv',label:'Current sheet · CSV values'},{value:'json',label:'Entire project · JSON backup'}],'xlsx')+'<p class="hint">Excel exports keep formulas, number formats, bold/italic/fills, hierarchy (outline levels), frozen columns, hyperlinks and comments as notes. A formula with no faithful Excel equivalent is exported as its value with the original formula in a cell note.</p>',async f=>{if(f.format.startsWith('xlsx')){const ids=f.format==='xlsx'?[cur.id]:f.format==='xlsx-folder'?folderSheets.map(x=>x.id):currentSheets().map(x=>x.id);const name=f.format==='xlsx'?cur.name:f.format==='xlsx-folder'?(state.folders.find(x=>x.id===cur.folderId)?.name||cur.name):(state.workspaces.find(w=>w.id===workspaceId)?.name||'Workspace');toast('Building Excel workbook…');const r=await fetch('/api/export-xlsx',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,sheetIds:ids,fileName:name})});if(!r.ok){const e=await r.json().catch(()=>({error:'Export failed'}));throw Error(e.error);}const st=JSON.parse(r.headers.get('X-Export-Stats')||'{}'),blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast(`Exported ${ids.length} sheet${ids.length===1?'':'s'} · ${st.translated||0} live formulas${st.values?` · ${st.values} kept as values (see cell notes)`:''}`);return true;}if(f.format==='json')download('sheets-backup.json',JSON.stringify(state,null,2),'application/json');else{const s=sheet(),cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';download(s.name+'.csv',[s.columns.map(c=>cell(c.name)).join(','),...s.rows.map(r=>s.columns.map(c=>cell(val(s,r,c))).join(','))].join('\r\n'),'text/csv');}},'Download');},
