 'view-options':()=>{const s=sheet(),cfg=s.viewConfig||{},dates=s.columns.filter(c=>c.type==='date'),lanes=s.columns.filter(c=>['select','contact','text'].includes(c.type));modal('View options',`<h3>Visible columns</h3><div class="column-checks">${s.columns.map((c,i)=>`<label class="check-field"><input type="checkbox" name="visible-${c.id}" ${!c.hidden?'checked':''} ${i===0?'disabled':''}>${esc(c.name)}</label>`).join('')}</div><div class="form-two">${selectField('Board lanes','boardColumnId',lanes.map(c=>({value:c.id,label:c.name})),cfg.boardColumnId||colBy(s,'Status')?.id)}${selectField('Calendar date','dateColumnId',dates.map(c=>({value:c.id,label:c.name})),cfg.dateColumnId||colBy(s,'Due')?.id)}${selectField('Timeline start','startColumnId',dates.map(c=>({value:c.id,label:c.name})),cfg.startColumnId||colBy(s,'Start')?.id)}${selectField('Timeline end','endColumnId',dates.map(c=>({value:c.id,label:c.name})),cfg.endColumnId||colBy(s,'Due')?.id)}</div><p class="hint">View settings are saved with this sheet. Hidden columns remain available to formulas, reports, and row details.</p>`,f=>mutate('Updated view options',n=>{const sh=n.sheets.find(x=>x.id===s.id);sh.columns.forEach((c,i)=>c.hidden=i===0?false:!f['visible-'+c.id]);sh.viewConfig={boardColumnId:f.boardColumnId||'',dateColumnId:f.dateColumnId||'',startColumnId:f.startColumnId||'',endColumnId:f.endColumnId||''};}));},
