function formBuilder(s,existing){const cols=s.columns.filter(c=>!c.formula);modal(existing?'Edit form':'Build a form',field('Form name','name',existing?.name||'','text','required')+field('Description','description',existing?.description||'')+`<div class="builder-section"><h3>Fields to collect</h3><div class="form-field-list">${cols.map(c=>`<div class="form-field-choice"><label class="check-field"><input type="checkbox" name="include-${c.id}" ${!existing||existing.columnIds.includes(c.id)?'checked':''}>${esc(c.name)}</label><label class="check-field required-toggle"><input type="checkbox" name="required-${c.id}" ${(existing?.requiredIds||[s.columns[0].id]).includes(c.id)?'checked':''}>Required</label></div>`).join('')}</div></div><p class="hint">Submissions create rows in ${esc(s.name)}. This form is available in the local app.</p>`,f=>{const columnIds=cols.filter(c=>f['include-'+c.id]).map(c=>c.id);if(!columnIds.length)throw Error('Choose at least one field.');return mutate('Saved form: '+f.name,n=>{const sh=n.sheets.find(x=>x.id===s.id),form={id:existing?.id||uid(),name:f.name,description:f.description,columnIds,requiredIds:columnIds.filter(id=>f['required-'+id])};const i=sh.forms.findIndex(x=>x.id===form.id);if(i<0)sh.forms.push(form);else sh.forms[i]=form;});});}

