 'tester-profile':()=>modal('Your testing profile',field('Name','name',testerName,'text','required maxlength="60"')+'<p class="hint">This name labels your feedback and activity on this Mac. It is not a login account.</p>',f=>{testerName=f.name.trim()||'Tester';localStorage.setItem('sheets-tester',testerName);render();}),
 'new-feedback':()=>modal('Leave feedback',field('What did you notice?','title','','text','required maxlength="140" placeholder="A short, specific summary"')+`<div class="form-two">${selectField('Type','kind',['Bug','Improvement','Question'],'Bug')}${selectField('Area','area',['Sheets','Reports','Dashboards','Forms','Automations','Navigation','Other'],page==='reports'?'Reports':page==='dashboards'?'Dashboards':'Sheets')}</div><label class="field">Details<textarea name="description" required placeholder="What happened? What did you expect?"></textarea></label><label class="field">Steps to reproduce (optional)<textarea name="steps" placeholder="1. Open a sheet…"></textarea></label><p class="hint">Recorded as ${esc(testerName)}.</p>`,f=>mutate('Submitted feedback',n=>{n.feedback||=[];n.feedback.push({id:uid(),title:f.title,kind:f.kind,area:f.area,description:f.description,steps:f.steps,by:testerName,at:new Date().toISOString(),status:'Open'});}),'Submit feedback'),
 'refresh-state':async()=>{if(saving||editQueue.pending)return toast('Wait for pending saves to finish.');const r=await fetch('/api/state');if(!r.ok)throw Error('Unable to refresh. Try again.');({state,revision}=await r.json());remoteChanged=false;conflictDraft=null;editQueue.clearConflict();dialog.close();render();toast('Loaded the latest workspace');},
