 'open-form':el=>{const s=state.sheets.find(s=>s.id===el.dataset.sheet),form=s.forms.find(f=>f.id===el.dataset.id),r=blankRow(s),cols=s.columns.filter(c=>form.columnIds.includes(c.id)&&!isReadOnly(c));modal(form.name,`<p>${esc(form.description)}</p>`+cols.map(c=>cellField(s,r,c,c.id)).join(''),f=>{const cells=Object.fromEntries(cols.map(c=>{const v=readCellField(c,c.id,f);validateCell(c,v);if((form.requiredIds||[s.columns[0].id]).includes(c.id)&&(v===''||Array.isArray(v)&&!v.length))throw Error('Complete '+c.name);return [c.id,v];}));return mutate('Form submission: '+s.name,n=>n.sheets.find(x=>x.id===s.id).rows.push(blankRow(s,cells)));},'Submit');},
 'delete-column':el=>{const id=el.dataset.id;modal('Delete column','<p>Delete this column and its values? Filters, format rules and workflows that refer to it will also be removed. Formulas using its name will need updating.</p>',()=>mutate('Deleted column',n=>{const s=n.sheets.find(s=>s.id===sheetId);if(s.columns[0].id===id)throw Error('The primary column cannot be deleted.');s.columns=s.columns.filter(c=>c.id!==id);s.rows.forEach(r=>delete r.cells[id]);s.forms.forEach(f=>{f.columnIds=f.columnIds.filter(x=>x!==id);f.requiredIds=f.requiredIds?.filter(x=>x!==id);});s.savedFilters=(s.savedFilters||[]).filter(f=>!f.conditions.some(c=>c.columnId===id));s.formatRules=(s.formatRules||[]).filter(f=>!f.conditions.some(c=>c.columnId===id)&&!f.targetIds.includes(id));s.sorts=(s.sorts||[]).filter(f=>f.columnId!==id);s.automations=s.automations.filter(a=>a.columnId!==id&&a.targetColumnId!==id&&!a.actions?.some(x=>x.columnId===id)&&!a.conditions?.some(x=>x.columnId===id));n.requests.filter(q=>q.sheetId===s.id).forEach(q=>q.columnIds=q.columnIds.filter(x=>x!==id));}),'Delete column');},
