document.addEventListener('focusin',e=>{const el=e.target.closest('[data-row][data-col]');if(el&&page==='sheet'){activeCell={sheetId,rowId:el.dataset.row,colId:el.dataset.col};document.querySelectorAll('.active-cell').forEach(el=>el.classList.remove('active-cell'));el.closest('td')?.classList.add('active-cell');const caption=$('.selection-caption');if(caption&&!selected.size)caption.textContent=sheet().columns.find(c=>c.id===el.dataset.col)?.name||'';}if(e.target.matches('input.cell-input')&&(numericTypes.includes(sheet()?.columns.find(c=>c.id===e.target.dataset.col)?.type)||sheet()?.columns.find(c=>c.id===e.target.dataset.col)?.numericFormat))e.target.value=e.target.dataset.raw||'';});
document.addEventListener('input',e=>{if(e.target.id==='column-search')dialog.querySelectorAll('[data-column-name]').forEach(el=>el.hidden=!el.dataset.columnName.includes(e.target.value.toLowerCase()));if(e.target.id==='formula-source')updateFormulaPreview();if(e.target.id==='comment-composer'){const before=e.target.value.slice(0,e.target.selectionStart),query=before.match(/@([^\s@\[\]]*)$/)?.[1]?.toLowerCase();dialog.querySelectorAll('[data-action="insert-mention"]').forEach(el=>el.hidden=query!==undefined&&!el.dataset.name.toLowerCase().includes(query));}});
document.addEventListener('change',e=>{if($('#formula-source')&&['scope','column','row'].includes(e.target.name)){if(e.target.name==='column'){const s=sheet(),c=s.columns.find(c=>c.id===e.target.value),row=s.rows.find(r=>r.id===dialog.querySelector('[name=\"row\"]').value),raw=row?.cells[c.id];$('#formula-source').value=c.formula||(typeof raw==='string'&&raw.startsWith('=')?raw:'');dialog.querySelector('[name=\"scope\"]').value=c.formula?'column':'cell';}updateFormulaPreview();}});

Object.assign(actions,{'workspace-workflows':el=>{sheetId=el.dataset.id;workflowManager();}});
function timelineRanges(s,rows,c){const mapped={...s,columns:[...s.columns,{id:'__timeline_start',name:'Timeline start',type:'date'},{id:'__timeline_end',name:'Timeline end',type:'date'}],rows:rows.map(r=>({...r,cells:{...r.cells,__timeline_start:r.cells[c.id]?.start||'',__timeline_end:r.cells[c.id]?.end||''}})),viewConfig:{...s.viewConfig,startColumnId:'__timeline_start',endColumnId:'__timeline_end'}};return timeline(mapped,mapped.rows);}


function metricsTable(metrics){return `<div class="planning-scroll"><table class="grid" style="width:${cols.reduce((n,c)=>n+(c.width||150),0)+202}px"><thead><tr><th>Sheet</th><th>Leaf items</th><th>Complete</th><th>Overdue</th><th>Mapped cost</th></tr></thead><tbody>${metrics.map(m=>`<tr><td>${button(esc(m.name),'sheet',`data-id="${m.sheetId}"`)}</td><td>${fmt(m.items)}</td><td>${m.completion}%</td><td>${fmt(m.overdue)}</td><td>${fmt(m.cost)}</td></tr>`).join('')}</tbody></table></div>`;}
function basePlanningDetail(kind,x){
 if(kind==='portfolios')return metricsTable(portfolioMetrics(state,x));
 if(kind==='scenarios'){
  const before=portfolioMetrics(state,x),after=portfolioMetrics(scenarioState(state,x),x),sum=a=>a.reduce((n,m)=>n+m.cost,0);
  return `<p>Live cost: <b>${fmt(sum(before))}</b> · Scenario: <b>${fmt(sum(after))}</b> · Difference: <b>${fmt(sum(after)-sum(before))}</b></p>${metricsTable(after)}<h3>What-if changes</h3>${(x.changes||[]).map((ch,i)=>{const s=state.sheets.find(s=>s.id===ch.sheetId),r=s?.rows.find(r=>r.id===ch.rowId),c=s?.columns.find(c=>c.id===ch.columnId);return `<p>${esc(s?.name)} · ${esc(r?title(s,r):'Deleted row')} · ${esc(c?.name)} → ${esc(displayCell(ch.value,c||{}))} ${button('Remove','scenario-remove',`data-id="${x.id}" data-index="${i}"`)}</p>`;}).join('')}${button('+ What-if change','scenario-change',`data-id="${x.id}"`)}<p class="hint">Compares against current live data each time. Source formulas recalculate in the scenario. Source sheets stay unchanged.</p>`;
 }
 if(kind==='dataTables')return `<p>${x.rows.length} rows · ${x.columns.length} columns · Snapshot ${esc(x.refreshedAt||'')}</p>${button('Create sheet from table','table-materialize',`data-id="${x.id}"`)} ${button('Refresh from source','table-refresh',`data-id="${x.id}"`)}<p class="hint">Refreshing replaces this snapshot; sheets created from it remain independent.</p><div class="planning-scroll"><table class="grid" style="width:${cols.reduce((n,c)=>n+(c.width||150),0)+202}px"><thead><tr>${x.columns.map(c=>`<th>${esc(c.name)}</th>`).join('')}</tr></thead><tbody>${x.rows.slice(0,20).map(r=>`<tr>${x.columns.map(c=>`<td>${esc(displayCell(r.cells[c.id],c))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="hint">Preview shows up to 20 rows.</p>`;
 const s=state.sheets.find(s=>s.id===x.sheetId);if(!s)return '<p>Source sheet unavailable.</p>';
 const rows=viewRows(state,x),cols=x.columnIds.map(id=>s.columns.find(c=>c.id===id)).filter(Boolean);
 return `<p>${rows.length} matching rows · ${esc(s.name)}</p><div class="planning-scroll"><table class="grid" style="width:${cols.reduce((n,c)=>n+(c.width||150),0)+202}px"><thead><tr>${cols.map(c=>`<th>${esc(c.name)}</th>`).join('')}<th></th></tr></thead><tbody>${rows.slice(0,100).map(r=>`<tr>${cols.map(c=>`<td style="${styleText(cellFormat(s,r,c,val))}">${fieldPolicy(state,x,r).get(c.id)?.visible?esc(displayCell(val(s,r,c),c)):'—'}</td>`).join('')}<td>${button('Open','dynamic-row',`data-view="${x.id}" data-row="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div>${rows.length>100?'<p>Showing first 100 rows. Narrow the filter to see more.</p>':''}`;
}
function planningConfig(kind,existing,sourceId){
 const x=existing||{...workspacePlan(state,workspaceId),id:uid(),name:kind==='portfolios'?'Workspace portfolio':kind==='scenarios'?'Baseline scenario':'',...(sourceId?{sheetId:sourceId}: {})},s=state.sheets.find(s=>s.id===(x.sheetId||sheetId))||currentSheets()[0];
 if(!s)return toast('Create a source sheet first.');
 const mappings=['statusColumn','costColumn','dueColumn'].map((key,i)=>selectField(['Status field','Cost field','Due-date field'][i],key,[{value:'',label:'Not mapped'},...sourceFields().map(name=>({value:name,label:name}))],x[key]||'')).join('');
 let body=field('Name','name',x.name,'text','required');
 if(['portfolios','scenarios'].includes(kind))body+=sourceChecks(x.sheetIds)+mappings+currentSheets().map(s=>`<details><summary>Field mappings · ${esc(s.name)}</summary>${['statusColumn','progressColumn','costColumn','dueColumn'].map((key,i)=>selectField(['Status','Progress / % complete','Cost','Due date'][i],'map-'+s.id+'-'+key,[{value:'',label:'Use default mapping'},...s.columns.map(c=>({value:c.id,label:c.name}))],x.sheetMappings?.[s.id]?.[key]||'')).join('')}${['budget','actual'].map(kind=>{const m=x.sheetMappings?.[s.id]||{},cur=m[kind+'Summary']?'sum:'+m[kind+'Summary']:m[kind+'Column']?'col:'+m[kind+'Column']:'';return selectField(kind==='budget'?'Budget (for budget vs actual)':'Actual / spent to date','map-'+s.id+'-'+kind,[{value:'',label:'Not mapped'},...(s.summaryFields||[]).map(f=>({value:'sum:'+f.name,label:'Sheet summary · '+f.name})),...s.columns.map(c=>({value:'col:'+c.id,label:'Sum of leaf rows · '+c.name}))],cur);}).join('')}<p class="hint">Prefer a sheet-summary total for budgets whose rows include subtotals, so nothing is counted twice.</p></details>`).join('');
 else if(!existing)body+=selectField('Source sheet','sheetId',currentSheets().map(s=>({value:s.id,label:s.name})),s.id);
 if(kind==='dataTables'&&existing)body+=`<p class="hint">Renaming keeps imported records and connections. Use Refresh from source to explicitly replace the snapshot.</p>`;
 if(kind==='dynamicViews'&&existing)sheetId=s.id;
 if(kind==='dynamicViews'&&existing)body+=`<p>Source: ${esc(s.name)}</p><h3>Visible / editable columns</h3>${s.columns.map(c=>`<div class="form-two"><label class="check-field"><input type="checkbox" name="visible-${c.id}" ${x.columnIds.includes(c.id)?'checked':''}>${esc(c.name)}</label><label class="check-field"><input type="checkbox" name="editable-${c.id}" ${x.editableIds.includes(c.id)?'checked':''} ${isReadOnly(c)?'disabled':''}>Editable</label></div>`).join('')}<h3>Row filter</h3>${conditionsUI(x.conditions||[],x.match||'all')}`;
 // The shared filter builder reads the current sheet.
 if(kind==='dynamicViews'&&existing)sheetId=s.id;
 modal(existing?'Configure '+planningLabels[kind]:'Create '+planningLabels[kind],body,async f=>{
  const item={...x,name:f.name.trim()};
  if(['portfolios','scenarios'].includes(kind)){item.sheetIds=currentSheets().filter(s=>f['source-'+s.id]).map(s=>s.id);for(const key of ['statusColumn','costColumn','dueColumn'])item[key]=f[key];item.sheetMappings=Object.fromEntries(currentSheets().map(s=>{const m=Object.fromEntries(['statusColumn','progressColumn','costColumn','dueColumn'].map(key=>[key,f['map-'+s.id+'-'+key]||'']));for(const kind of ['budget','actual']){const v=f['map-'+s.id+'-'+kind]||'';m[kind+'Summary']=v.startsWith('sum:')?v.slice(4):'';m[kind+'Column']=v.startsWith('col:')?v.slice(4):'';}return [s.id,m];}));item.changes=(item.changes||[]).filter(ch=>item.sheetIds.includes(ch.sheetId));}
  if(kind==='dataTables'&&!existing){const source=state.sheets.find(s=>s.id===f.sheetId);Object.assign(item,tableSnapshot(source));}
  if(kind==='dynamicViews'){
   if(existing){item.columnIds=s.columns.filter(c=>f['visible-'+c.id]).map(c=>c.id);item.editableIds=s.columns.filter(c=>f['visible-'+c.id]&&f['editable-'+c.id]&&!isReadOnly(c)).map(c=>c.id);item.conditions=readConditions();item.match=f.match;}
   else{const source=state.sheets.find(s=>s.id===f.sheetId);Object.assign(item,{sheetId:source.id,columnIds:suggestViewColumns(source),editableIds:[],conditions:[],match:'all',allowComments:true});}
  }
  const ok=await mutate('Saved '+planningLabels[kind],n=>{const i=n[kind].findIndex(y=>y.id===item.id);if(i<0)n[kind].push(item);else n[kind][i]=item;});if(ok){planningSelection=item.id;page=kind;render();}return ok;
 });dialog.classList.add('wide-dialog');
}
function tableSnapshot(s){return {...snapshotTable(state,s),refreshedAt:new Date().toISOString()};}
Object.assign(actions,{
 'planning-new':el=>planningConfig(el.dataset.kind,null,el.dataset.source),
 'planning-config':el=>planningConfig(el.dataset.kind,state[el.dataset.kind].find(x=>x.id===el.dataset.id)),
 'planning-delete':el=>{const {kind,id}=el.dataset;modal('Delete '+planningLabels[kind],'<p>Delete this saved definition? Source sheets stay unchanged.</p>',()=>mutate('Deleted '+planningLabels[kind],n=>{n[kind]=n[kind].filter(x=>x.id!==id);}),'Delete');},
 'scenario-change':el=>{
  const scenario=state.scenarios.find(x=>x.id===el.dataset.id),sources=state.sheets.filter(s=>scenario.sheetIds.includes(s.id));
  modal('Choose a scenario sheet',selectField('Sheet','sheetId',sources.map(s=>({value:s.id,label:s.name})),sources[0].id),f=>{setTimeout(()=>scenarioChange(scenario,state.sheets.find(s=>s.id===f.sheetId)),0);return true;},'Continue');
 },
 'scenario-remove':el=>mutate('Removed what-if change',n=>{n.scenarios.find(x=>x.id===el.dataset.id).changes.splice(Number(el.dataset.index),1);}),
 'table-refresh':el=>{const x=state.dataTables.find(x=>x.id===el.dataset.id),s=state.sheets.find(s=>s.id===x.sourceSheetId);if(!s)return toast('Source sheet no longer exists. Configure a new source.');modal('Refresh snapshot','<p>Replace the stored snapshot with current source values?</p>',()=>mutate('Refreshed data table',n=>Object.assign(n.dataTables.find(y=>y.id===x.id),tableSnapshot(s))),'Refresh');},
 'table-materialize':async el=>{const x=state.dataTables.find(x=>x.id===el.dataset.id),id=uid(),ids=new Map(x.columns.map(c=>[c.id,uid()])),columns=x.columns.map(c=>({...structuredClone(c),id:ids.get(c.id)}));const ok=await mutate('Created sheet from data table',n=>n.sheets.push({id,workspaceId,folderId:null,name:x.name+' copy',description:'Created from local DataTable snapshot',columns,rows:x.rows.map(r=>blankRow({columns},Object.fromEntries(Object.entries(r.cells).map(([key,value])=>[ids.get(key),structuredClone(value)])))),forms:[],automations:[]}));if(ok){sheetId=id;page='sheet';render();}},
 'dynamic-row':el=>{
  const v=state.dynamicViews.find(v=>v.id===el.dataset.view),s=state.sheets.find(s=>s.id===v.sheetId),r=s.rows.find(r=>r.id===el.dataset.row),cols=v.columnIds.map(id=>s.columns.find(c=>c.id===id)).filter(Boolean),editable=cols.filter(c=>v.editableIds.includes(c.id)&&!isReadOnly(c)&&!r.locked&&!String(r.cells[c.id]||'').startsWith('='));
  modal('View row',cols.map(c=>editable.includes(c)?cellField(s,r,c,'dv-'+c.id):`<p><b>${esc(c.name)}</b><br>${esc(displayCell(val(s,r,c),c))}</p>`).join(''),f=>mutate('Edited row through Dynamic View',n=>{const row=n.sheets.find(x=>x.id===s.id).rows.find(x=>x.id===r.id);for(const c of editable){const value=readCellField(c,'dv-'+c.id,f,r.cells[c.id],s);validateCell(c,value);row.cells[c.id]=value;}}));
 }
});
function scenarioChange(scenario,s){
 const rows=s.rows.filter(r=>!r.locked),cols=s.columns.filter(c=>!isReadOnly(c));if(!rows.length||!cols.length)return toast('No editable cells in this sheet.');
 modal('What-if cell value',selectField('Row','rowId',rows.map(r=>({value:r.id,label:title(s,r)})),rows[0].id)+selectField('Column','columnId',cols.map(c=>({value:c.id,label:c.name})),cols[0].id)+field('New value','value')+'<p class="hint">Use comma-separated names for people; dates use YYYY-MM-DD. Rich connected/location/link values should be edited in a sheet.</p>',f=>{const c=cols.find(c=>c.id===f.columnId),value=parseCell(c,f.value);validateCell(c,value);return mutate('Saved what-if change',n=>{const x=n.scenarios.find(x=>x.id===scenario.id);x.changes=x.changes.filter(ch=>!(ch.sheetId===s.id&&ch.rowId===f.rowId&&ch.columnId===c.id));x.changes.push({sheetId:s.id,rowId:f.rowId,columnId:c.id,value,baseValue:structuredClone(s.rows.find(r=>r.id===f.rowId).cells[c.id]??'')});});});
}

