Object.assign(actions,{'import-notes':()=>{const s=sheet();modal('Excel import notes',`<p>Source: ${esc(s.source.file)}</p><p>Original formula definitions and conditional-formatting rules were absent from this export. Exported values and static cell styles were retained. Hierarchy follows exported indentation.</p><h3>Unmapped comment records</h3><p>These records had no usable row label; they were retained without assigning them to a row.</p>${(s.source.unmatchedComments||[]).map(c=>`<article><b>${esc(c[2])}</b> <small>${esc(c[3])}</small><p>${esc(c[1])}</p></article>`).join('')||'<p>None.</p>'}`,()=>true,'Done');}});

function formulaAudit(){const s=sheet(),cols=s.columns.filter(c=>c.formula||c.formulaInference);modal('Formula audit',`<p>Inferred formulas are reconstructed from exported values, not recovered originals. Exported exceptions remain literal. Restoring a column removes its formula and reveals its retained cell values.</p>${cols.map(c=>{const info=c.formulaInference,overrides=s.rows.filter(r=>r.formulaOverrides?.[c.id]);return `<article class="formula-audit-card"><h3>${esc(c.name)} · ${c.formula?'Active':'Restored values'}</h3><pre>${esc(c.formula||info?.formula||'')}</pre>${info?`<p><b>Inferred</b> · ${info.matched}/${info.eligible} populated values matched the ${esc(info.asOf)} export. ${overrides.length} rows retain exported values.</p><p>${esc(info.reason)}</p>`:'<p>User formula</p>'}${c.formula?button('Restore retained values','formula-restore',`data-id="${c.id}"`):''}${overrides.length?`<details><summary>Preserved exceptions</summary>${overrides.map(r=>`<p>Row ${s.rows.indexOf(r)+1}: ${esc(displayCell(r.cells[c.id],c))} ${button('Use formula','formula-release',`data-col="${c.id}" data-row="${r.id}"`)}</p>`).join('')}</details>`:''}</article>`;}).join('')||'<p>No column formulas yet.</p>'}${(s.formulaSuggestions||[]).map(x=>`<article class="formula-audit-card"><h3>${esc(x.target)} · Review only</h3><pre>${esc(x.formula)}</pre><p>${x.matched}/${x.eligible} exported values match. ${esc(x.reason)} No formula was applied.</p><details><summary>Differences</summary>${x.exceptions.map(e=>`<p>Row ${e.row}: exported ${esc(e.original)}; candidate ${esc(e.predicted)}</p>`).join('')}</details></article>`).join('')}`,()=>true,'Done');dialog.classList.add('wide-dialog');}
Object.assign(actions,{
 'formula-audit':formulaAudit,
 'formula-restore':el=>{const col=sheet().columns.find(c=>c.id===el.dataset.id);modal('Restore retained column values',`<p>Remove the formula from ${esc(col.name)} and reveal the underlying cell values?</p>`,()=>mutate('Restored values in '+col.name,n=>{const s=n.sheets.find(s=>s.id===sheetId);s.columns.find(c=>c.id===col.id).formula='';for(const r of s.rows)if(r.formulaOverrides)delete r.formulaOverrides[col.id];}),'Restore');},
 'formula-release':el=>{const {col,row}=el.dataset;modal('Use inferred formula','<p>This row will recalculate using the column formula. Its retained value stays available if the column formula is restored.</p>',()=>mutate('Released inferred formula exception',n=>{delete n.sheets.find(s=>s.id===sheetId).rows.find(r=>r.id===row).formulaOverrides[col];}),'Use formula');},
 'fill-formula-down':()=>{const f=Object.fromEntries(new FormData($('#modal-form'))),s=sheet(),c=s.columns.find(c=>c.id===f.column),start=s.rows.findIndex(r=>r.id===f.row),formula=f.formula.trim();if(!formula.startsWith('='))throw Error('Enter a formula starting with =');if(c.formula)throw Error('Clear the column formula before filling individual cells.');if(start<0)throw Error('Choose a source row.');const targets=s.rows.slice(start);if(targets.some(r=>r.locked))throw Error('Unlock target rows before filling formulas.');modal('Fill formula down',`<p>Write formulas to ${targets.length} cells in ${esc(c.name)}, starting at row ${start+1}? Existing values will be replaced. Relative references adjust for each row; absolute references stay fixed.</p>`,()=>mutate('Filled formulas down '+c.name,n=>{const sh=n.sheets.find(x=>x.id===s.id);for(let i=start;i<sh.rows.length;i++)sh.rows[i].cells[c.id]=translateFormula(formula,i-start,0);}),'Fill formulas');}
});

async function serverChange(url,body={}){if(saving||editQueue.pending)throw Error('Wait for the current save.');saving=true;try{const x=await request(url,{...body,revision});state=x.state;revision=x.revision;remoteChanged=false;render();return x;}finally{saving=false;}}
function planningDetail(kind,x){
 if(kind==='scenarios'){
  const summary=scenarioSummary(state,x);return `<div class="scenario-score"><span>Selected projects <b>${summary.selectedIds.length}/${x.sheetIds.length}</b></span><span>Cost <b>${fmt(summary.cost)}</b>${x.budgetLimit!==''&&x.budgetLimit!=null?' / '+fmt(x.budgetLimit):''}</span><span>Cost change <b>${fmt(summary.costDelta)}</b></span><span>Effort <b>${fmt(summary.effort)}</b>${x.capacityLimit!==''&&x.capacityLimit!=null?' / '+fmt(x.capacityLimit):''}</span><span class="${summary.overBudget||summary.overCapacity?'error-value':''}">${summary.overBudget?'Over budget by '+fmt(summary.overBudget):summary.overCapacity?'Over capacity by '+fmt(summary.overCapacity):'Within configured limits'}</span></div><div class="action-row">${button('Select projects & constraints','scenario-projects',`data-id="${x.id}"`)}${button('Recommend selection','scenario-recommend',`data-id="${x.id}"`)}${button('Duplicate scenario','scenario-duplicate',`data-id="${x.id}"`)}${button('Apply included cell changes','scenario-apply',`data-id="${x.id}"`)}</div><p class="hint">Recommendation uses priority order and available budget/capacity; it is a planning heuristic. Applying changes checks the original source values and row locks.</p>${metricsTable(summary.after)}<h3>What-if changes</h3>${(x.changes||[]).map((ch,i)=>{const s=state.sheets.find(s=>s.id===ch.sheetId),r=s?.rows.find(r=>r.id===ch.rowId),c=s?.columns.find(c=>c.id===ch.columnId);return `<p>${esc(s?.name)} · ${esc(r?title(s,r):'Deleted row')} · ${esc(c?.name)} → ${esc(displayCell(ch.value,c||{}))} ${button('Remove','scenario-remove',`data-id="${x.id}" data-index="${i}"`)}</p>`;}).join('')}${button('+ What-if change','scenario-change',`data-id="${x.id}"`)}${x.appliedAt?'<p>Applied '+esc(x.appliedAt)+'</p>':''}`;
 }
 if(kind==='dataTables')return `<div class="action-row">${button('Import / merge CSV','table-ingest',`data-id="${x.id}"`)}${button('Add sheet connection','table-connect',`data-id="${x.id}"`)}</div>${(x.connections||[]).map(c=>`<article class="connection-card"><b>${esc(c.name||state.sheets.find(s=>s.id===c.sheetId)?.name)}</b><p>${esc(c.mode||'merge')} · ${c.auto?'Automatic on save':'Manual'} · ${c.mappings.length} mapped fields</p>${c.lastSync?`<p>${c.lastSync.inserted} added, ${c.lastSync.updated} updated, ${c.lastSync.skippedLocked} locked rows skipped</p>`:''}${c.syncError?`<p class="error-value">${esc(c.syncError)}</p>`:''}${button('Sync now','table-sync',`data-id="${x.id}" data-connection="${c.id}"`)}${button('Remove connection','table-disconnect',`data-id="${x.id}" data-connection="${c.id}"`)}</article>`).join('')}${basePlanningDetail(kind,x)}`;
 if(kind==='dynamicViews')return `<div class="action-row">${button('Field rules & required values','view-field-rules',`data-id="${x.id}"`)}</div>${basePlanningDetail(kind,x)}`;
 return basePlanningDetail(kind,x);
}
function connectionFields(table,target){
 return selectField('Unique table key','tableKeyId',table.columns.map(c=>({value:c.id,label:c.name})),table.columns[0].id)+selectField('Unique target key','keyColumnId',target.columns.filter(c=>!isReadOnly(c)).map(c=>({value:c.id,label:c.name})),target.columns.find(c=>!isReadOnly(c))?.id)+selectField('Sync behavior','mode',[{value:'merge',label:'Add new keys and update existing'},{value:'append',label:'Add new keys only'},{value:'update',label:'Update existing keys only'}],'merge')+'<h3>Field mapping</h3>'+table.columns.map(c=>selectField(c.name,'mapping-'+c.id,[{value:'',label:'Do not sync'},...target.columns.filter(c=>!isReadOnly(c)).map(t=>({value:t.id,label:t.name}))],target.columns.find(t=>t.name===c.name&&!isReadOnly(t))?.id||'')).join('')+'<h3>Optional source filter</h3>'+selectField('Source field','filterColumn',[{value:'',label:'All records'},...table.columns.map(c=>({value:c.id,label:c.name}))],'')+selectField('Comparison','filterOperator',sheetOperators.map(([value,label])=>({value,label})),'equals')+field('Filter value','filterValue')+'<label class="check-field"><input type="checkbox" name="auto">Refresh and sync automatically on project saves</label><p class="hint">Keys must be unique. Sync never deletes rows and skips locked targets. Include the key in the mapping. Calculated and system fields cannot be sync targets.</p>';
}
