function isoWeekInput(value){const d=new Date(value+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+4-(d.getUTCDay()||7));const first=new Date(Date.UTC(d.getUTCFullYear(),0,1)),week=Math.ceil((((d-first)/864e5)+1)/7);return d.getUTCFullYear()+'-W'+String(week).padStart(2,'0');}
