function readRoute(){const [path,search='']=location.hash.slice(1).split('?'),candidate=path.replace(/^\//,''),params=new URLSearchParams(search);if(!['home','sheet','reports','dashboards','forms','automations','activity','testing',...Object.keys(planningLabels)].includes(candidate))return;const locationState=resolveLocation(state,{page:candidate,workspaceId:params.get('workspace')||workspaceId,sheetId:params.get('sheet')||sheetId,view,reportId:params.get('report')||reportId,dashboardId});({page,workspaceId,sheetId,reportId}=locationState);planningSelection=params.get('item')||'';}
window.addEventListener('hashchange',()=>{if(state){readRoute();render();}});
function cachedReport(r){const key=revision+JSON.stringify(r);if(reportResultCache?.key!==key)reportResultCache={key,result:runReport(state,r)};return reportResultCache.result;}
function reportVisibleGroups(result,r){const key=JSON.stringify(r);if(key!==reportKey){reportPage=0;reportKey=key;}reportPage=Math.min(reportPage,Math.max(0,Math.ceil(result.rows.length/100)-1));const ordered=result.groups.flatMap(g=>g.rows),ids=new Set(ordered.slice(reportPage*100,reportPage*100+100));return result.groups.map(g=>({...g,totalRows:g.rows.length,rows:g.rows.filter(r=>ids.has(r))})).filter(g=>g.rows.length);}
function reportMappingFields(report){return currentSheets().map(s=>{const mapping=report.sheetMappings?.[s.id]||inferSheetMappings(s);return `<details class="mapping-details"><summary>${esc(s.name)}</summary><div class="form-two">${[['titleColumn','Item title'],['statusColumn','Status'],['progressColumn','Progress / % complete'],['ownerColumn','Owner'],['dueColumn','Due date'],['costColumn','Cost']].map(([key,label])=>selectField(label,'report-map-'+s.id+'-'+key,[{value:'',label:'Not mapped'},...s.columns.map(c=>({value:c.id,label:c.name}))],mapping[key]||'')).join('')}</div></details>`;}).join('');}
function readReportMappings(f){return Object.fromEntries(currentSheets().map(s=>[s.id,Object.fromEntries(['titleColumn','statusColumn','progressColumn','ownerColumn','dueColumn','costColumn'].map(key=>[key,f['report-map-'+s.id+'-'+key]||'']))]));}
function reportExportDialog(){const report=activeReport(),rows=cachedReport(report).rows.length;modal('Export report as PDF',`<div class="pdf-intro">${icon('reports',32)}<div><h3>${esc(report.name)}</h3><p>${fmt(rows)} matching rows · ${report.columns.length} columns · ${report.sheetIds.length} source sheets</p></div></div><div class="form-two">${selectField('Paper size','paper',[{value:'LETTER',label:'US Letter'},{value:'A4',label:'A4'}],'LETTER')}${selectField('Orientation','orientation',[{value:'landscape',label:'Landscape'},{value:'portrait',label:'Portrait'}],'landscape')}</div><label class="check-field"><input type="checkbox" name="includeSummary" checked>Include report summary</label><label class="check-field"><input type="checkbox" name="includeDetails" checked>Include detailed rows (uncheck for a group summary only)</label><label class="field">Report notes<textarea name="notes" maxlength="10000" placeholder="Add context, decisions, or recommendations for the reader."></textarea></label><p class="hint">Exports all matching rows, current calculated values, groups and selected columns. Wide tables continue in additional column sections. Table headers and page numbers repeat on every page.</p><div id="pdf-progress" role="status"></div>`,async f=>{const submit=dialog.querySelector('[type="submit"]');submit.disabled=true;$('#pdf-progress').textContent='Building your report…';try{const response=await fetch('/api/reports/pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({report,revision,options:{paper:f.paper,orientation:f.orientation,includeSummary:!!f.includeSummary,includeDetails:!!f.includeDetails,notes:f.notes}})});if(!response.ok)throw Error((await response.json()).error||'Could not export report');const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=report.name+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('PDF downloaded · '+fmt(rows)+' matching rows');return true;}finally{submit.disabled=false;if($('#pdf-progress'))$('#pdf-progress').textContent='';}},'Download PDF');}
function suggestViewColumns(s){const mapping=inferSheetMappings(s),ids=[mapping.titleColumn,mapping.statusColumn,mapping.progressColumn,mapping.ownerColumn,mapping.dueColumn,mapping.costColumn,...s.columns.filter(c=>!c.hidden).map(c=>c.id)];return [...new Set(ids.filter(Boolean))].slice(0,7);}
function statTiles(items){return `<div class="planning-stats">${items.map(([label,value,note])=>`<article><span>${label}</span><strong>${esc(value)}</strong><small>${esc(note||'')}</small></article>`).join('')}</div>`;}
function planningPage(){
 const items=state[page].filter(x=>x.workspaceId===workspaceId),selected=items.find(x=>x.id===planningSelection),live=['portfolios','scenarios'].includes(page),x=selected||(!planningSelection&&live?null:items[0]);
 const descriptions={portfolios:'Progress, costs, and dates across your source sheets.',scenarios:'Compare alternatives before you commit changes to live work.',dataTables:'Bring records together, then connect them to your sheets.',dynamicViews:'Focused workflows with the fields and edit rules your team needs.'};
 const library=`<aside class="planning-library"><span class="eyebrow">${planningLabels[page]}</span>${live?button(`<span>${icon('activity',17)} Live workspace</span><small>${currentSheets().length} source sheets</small>`,'planning-select','data-id=""',!x?'active':''):''}${items.map(item=>button(`<span>${icon(page,17)} ${esc(item.name)}</span><small>${page==='portfolios'||page==='scenarios'?item.sheetIds.length+' source sheets':page==='dataTables'?fmt(item.rows.length)+' records':'Focused sheet view'}</small>`,'planning-select',`data-id="${item.id}"`,x?.id===item.id?'active':'')).join('')}${button(icon('plus',15)+' Create new','planning-new',`data-kind="${page}"`,'planning-library-new')}<p>Saved in<br><strong>${esc(state.workspaces.find(w=>w.id===workspaceId)?.name)}</strong></p></aside>`;
 let body;
 if(!x&&live){const preview=workspacePlan(state,workspaceId);body=`<div class="live-planning-note"><span class="live-dot"></span><div><b>Live workspace preview</b><p>Uses your actual sheets with suggested field mappings. Save a ${page==='scenarios'?'scenario':'portfolio'} to choose sources and review the mappings.</p></div>${button(page==='scenarios'?'Create scenario':'Save portfolio','planning-new',`data-kind="${page}"`,'primary')}</div>${page==='portfolios'?portfolioCanvas(preview,true):scenarioBaseline(preview)}`;}
 else if(!x)body=planningSourceGallery(page);
 else body=`<div class="planning-item-heading"><div><span class="eyebrow">SAVED ${page==='scenarios'?'SCENARIO':page==='portfolios'?'PORTFOLIO':page==='dataTables'?'DATA TABLE':'VIEW'}</span><h2>${esc(x.name)}</h2></div><div class="action-row">${page==='portfolios'?button('Open source report','portfolio-report',`data-id="${x.id}"`):''}${button('Configure','planning-config',`data-kind="${page}" data-id="${x.id}"`)}${button(icon('more',16),'planning-delete',`data-kind="${page}" data-id="${x.id}" aria-label="Delete ${esc(x.name)}"`)}</div></div>${page==='portfolios'?portfolioCanvas(x):page==='scenarios'?scenarioCanvas(x):page==='dataTables'?dataTableCanvas(x):dynamicCanvas(x)}`;
 return pageHeader('PLANNING & DATA',planningLabels[page],descriptions[page],button(icon('plus',16)+' Create '+(page==='scenarios'?'scenario':page==='portfolios'?'portfolio':page==='dataTables'?'table':'view'),'planning-new',`data-kind="${page}"`,'primary'))+`<div class="planning-layout">${library}<section class="planning-workbench">${body}</section></div>`;
}
function portfolioCanvas(config,preview=false){
 const metrics=portfolioMetrics(state,config),sum=key=>metrics.reduce((n,m)=>n+m[key],0),mappedCosts=metrics.filter(m=>m.mapped.cost),mappedStatus=metrics.filter(m=>m.mapped.status||m.mapped.progress),mappedDates=metrics.filter(m=>m.mapped.due),count=sum('items');
 return budgetRollupSection(metrics)+statTiles([['Source sheets',metrics.length,'Selected in this portfolio'],['Leaf items',fmt(count),'Parent totals excluded'],['Mapped cost',mappedCosts.length?fmt(sum('cost')):'—',mappedCosts.length+'/'+metrics.length+' sheets mapped'],['Overdue',mappedDates.length?fmt(sum('overdue')):'—',mappedDates.length+'/'+metrics.length+' date fields mapped']])+`<section class="portfolio-projects"><div class="panel-heading"><div><h3>Project overview</h3><p>Each card represents one source sheet. Review overlapping projects before using combined totals.</p></div><span class="subtle-pill">${preview?'Suggested mappings':'Live calculations'}</span></div><div class="project-card-grid">${metrics.map(m=>`<article class="project-overview-card"><div class="project-card-heading"><span class="hub-sheet-icon">${icon('sheet',20)}</span><span class="badge ${m.overdue?'amber':'green'}">${m.mapped.due?(m.overdue?fmt(m.overdue)+' overdue':'No overdue items'):'Date not mapped'}</span></div><h3>${esc(m.name)}</h3><p>${fmt(m.items)} leaf items</p><div class="progress-label"><span>Completed items</span><b>${m.mapped.status||m.mapped.progress?m.completion+'%':'Not mapped'}</b></div><div class="mini-progress"><span style="width:${m.completion}%"></span></div><div class="project-metrics"><div><small>Mapped cost</small><b>${m.mapped.cost?fmt(m.cost):'—'}</b></div><div><small>Complete</small><b>${m.mapped.status||m.mapped.progress?fmt(m.complete):'—'}</b></div></div><details class="mapping-details"><summary>Source fields</summary><p>Status / progress: ${esc(m.fields.status||'Not mapped')}<br>Cost: ${esc(m.fields.cost||'Not mapped')}<br>Due: ${esc(m.fields.due||'Not mapped')}</p></details>${button('Open sheet '+icon('arrow',14),'sheet',`data-id="${m.sheetId}"`,'text-button')}</article>`).join('')||'<p>No source sheets yet. Create or import a sheet to begin.</p>'}</div></section>`;
}
function scenarioBaseline(config){return `<section class="scenario-intro"><div><span class="eyebrow">START WITH YOUR CURRENT PLAN</span><h2>Explore the next version of your plan.</h2><p>Create an alternative, adjust costs or dates, select projects, and compare the result with the live baseline. Changes stay in your scenario until you apply them.</p></div><ol><li><b>Choose your sources</b><span>Map the cost and date fields you want to model.</span></li><li><b>Make what-if changes</b><span>Adjust individual cells or apply a bulk cost/date change.</span></li><li><b>Compare and decide</b><span>Check budget and capacity, then apply reviewed cell changes.</span></li></ol></section>${scenarioComparison(config)}${portfolioCanvas(config,true)}`;}
function scenarioComparison(config){const items=state.scenarios.filter(x=>x.workspaceId===workspaceId),baseline=portfolioMetrics(state,config),baselineCost=baseline.reduce((n,m)=>n+m.cost,0);return `<section class="scenario-comparison"><div class="panel-heading"><div><h3>Compare alternatives</h3><p>Each saved scenario uses its own selected sources and mappings.</p></div></div><div class="planning-scroll"><table class="workbench-table"><thead><tr><th>Plan</th><th>Sources</th><th>Mapped cost</th><th>Δ vs own baseline</th><th>Effort</th><th>Constraints</th></tr></thead><tbody><tr><td>Live baseline</td><td>${config.sheetIds.length}</td><td>${fmt(baselineCost)}</td><td>—</td><td>—</td><td>No scenario limits</td></tr>${items.map(x=>{const m=scenarioSummary(state,x);return `<tr><td>${button(esc(x.name),'planning-select',`data-id="${x.id}"`,'text-button')}</td><td>${m.selectedIds.length}/${x.sheetIds.length}</td><td>${fmt(m.cost)}</td><td>${m.costDelta>0?'+':''}${fmt(m.costDelta)}</td><td>${fmt(m.effort)}</td><td>${m.overBudget?'Over budget by '+fmt(m.overBudget):m.overCapacity?'Over capacity by '+fmt(m.overCapacity):x.budgetLimit==null&&x.capacityLimit==null?'No limits set':'Within limits'}</td></tr>`;}).join('')}</tbody></table></div>${!items.length?'<p class="quiet-empty">Save your first scenario to compare it alongside the live baseline.</p>':''}</section>`;}
function scenarioCanvas(x){const summary=scenarioSummary(state,x);return statTiles([['Selected sources',summary.selectedIds.length+'/'+x.sheetIds.length,'Choose projects & priorities'],['Scenario cost',fmt(summary.cost),'Change: '+(summary.costDelta>0?'+':'')+fmt(summary.costDelta)],['Effort',fmt(summary.effort),x.capacityLimit!=null&&x.capacityLimit!==''?'Capacity '+fmt(x.capacityLimit):'No capacity limit'],['Budget remaining',x.budgetLimit!=null&&x.budgetLimit!==''?fmt(Number(x.budgetLimit)-summary.cost):'—',x.budgetLimit!=null&&x.budgetLimit!==''?'Limit '+fmt(x.budgetLimit):'No budget limit']])+`<div class="scenario-actions">${button('Adjust costs or dates','scenario-bulk',`data-id="${x.id}"`,'primary')}${button('Add cell change','scenario-change',`data-id="${x.id}"`)}${button('Projects & constraints','scenario-projects',`data-id="${x.id}"`)}${button('Recommend selection','scenario-recommend',`data-id="${x.id}"`)}${button('Duplicate','scenario-duplicate',`data-id="${x.id}"`)}${button('Apply changes to sheets','scenario-apply',`data-id="${x.id}" ${(x.changes||[]).length?'':'disabled'}`)}</div>${summary.overBudget||summary.overCapacity?`<p class="scenario-warning">${summary.overBudget?'Over budget by '+fmt(summary.overBudget)+'. ':''}${summary.overCapacity?'Over capacity by '+fmt(summary.overCapacity)+'.':''}</p>`:''}${scenarioComparison(x)}<section class="scenario-changes"><div class="panel-heading"><div><h3>What-if changes <span class="subtle-pill">${(x.changes||[]).length}</span></h3><p>Source values remain unchanged until you choose Apply changes to sheets.</p></div>${(x.changes||[]).length?button('Clear changes','scenario-clear',`data-id="${x.id}"`):''}</div><div class="planning-scroll"><table class="workbench-table"><thead><tr><th>Source / item</th><th>Field</th><th>Original</th><th>Scenario</th><th></th></tr></thead><tbody>${(x.changes||[]).slice(0,100).map((ch,i)=>{const s=state.sheets.find(s=>s.id===ch.sheetId),r=s?.rows.find(r=>r.id===ch.rowId),c=s?.columns.find(c=>c.id===ch.columnId);return `<tr><td>${esc(s?.name)}<small>${esc(r?title(s,r):'Missing row')}</small></td><td>${esc(c?.name)}</td><td>${esc(displayCell(ch.baseValue,c||{}))}</td><td>${esc(displayCell(ch.value,c||{}))}</td><td>${button('Remove','scenario-remove',`data-id="${x.id}" data-index="${i}"`)}</td></tr>`;}).join('')}</tbody></table></div>${!(x.changes||[]).length?'<p class="quiet-empty">No changes yet. Adjust costs or dates to model an alternative.</p>':''}${(x.changes||[]).length>100?`<p class="hint">Previewing 100 of ${x.changes.length} changes. All saved changes are included in the calculations and apply action.</p>`:''}</section><p class="hint">Recommendations use a priority-first heuristic. Applying checks source values and row locks. ${x.appliedAt?'Last applied '+esc(x.appliedAt):''}</p>`;}
function planningSourceGallery(kind){return `<section class="source-gallery"><span class="eyebrow">CHOOSE A SOURCE TO GET STARTED</span><h2>${kind==='dataTables'?'Your data, ready to connect.':'A focused view for every workflow.'}</h2><p>${kind==='dataTables'?'Create a snapshot, merge incoming CSV records, and sync mapped fields into connected sheets.':'Start with useful columns from a source sheet, then configure row filters, editable fields, and conditional rules.'}</p><div class="source-gallery-grid">${currentSheets().map(s=>`<article><span class="hub-sheet-icon">${icon('sheet',22)}</span><h3>${esc(s.name)}</h3><p>${fmt(s.rows.length)} rows · ${s.columns.length} columns</p>${button('Create '+(kind==='dataTables'?'data table':'view'),'planning-new',`data-kind="${kind}" data-source="${s.id}"`,'primary')}</article>`).join('')||'<p>Import or create a source sheet first.</p>'}</div></section>`;}
function dataTableCanvas(x){return statTiles([['Records',fmt(x.rows.length),'Stored table snapshot'],['Fields',x.columns.length,'Typed data columns'],['Connections',(x.connections||[]).length,'One-way sheet sync'],['Source refresh',x.refreshFromSource!==false?'Enabled':'Paused',x.refreshedAt?'Snapshot '+new Date(x.refreshedAt).toLocaleDateString():'Not refreshed']])+`<div class="scenario-actions">${button('Import / merge CSV','table-ingest',`data-id="${x.id}"`,'primary')}${button('Add connection','table-connect',`data-id="${x.id}"`)}${button('Refresh from source','table-refresh',`data-id="${x.id}"`)}${button('Create sheet from table','table-materialize',`data-id="${x.id}"`)}</div><div class="connection-grid">${(x.connections||[]).map(c=>`<article class="connection-card"><b>${esc(c.name||state.sheets.find(s=>s.id===c.sheetId)?.name)}</b><p>${esc(c.mode||'merge')} · ${c.auto?'Automatic on save':'Manual'} · ${c.mappings.length} mapped fields</p>${c.lastSync?`<p>${c.lastSync.inserted} added · ${c.lastSync.updated} updated · ${c.lastSync.skippedLocked} locked skipped</p>`:''}${c.syncError?`<p class="error-value">${esc(c.syncError)}</p>`:''}<div class="action-row">${button('Sync now','table-sync',`data-id="${x.id}" data-connection="${c.id}"`)}${button('Remove','table-disconnect',`data-id="${x.id}" data-connection="${c.id}"`)}</div></article>`).join('')}</div>${recordBrowser(x,'dataTables')}`;}
function dynamicCanvas(x){const s=state.sheets.find(s=>s.id===x.sheetId);return `<div class="dynamic-banner"><div><b>${esc(s?.name||'Missing source')}</b><p>${x.columnIds.length} visible fields · ${x.editableIds.length} editable · ${(x.conditions||[]).length} row conditions</p></div>${button('Field rules & required values','view-field-rules',`data-id="${x.id}"`)}</div>${recordBrowser(x,'dynamicViews')}<p class="hint">Edit rules are enforced by the view endpoint. This local workspace does not have authenticated private sharing.</p>`;}
function recordBrowser(x,kind){
 const prefs=browserState.get(x.id)||{page:0,query:''},s=kind==='dataTables'?x:state.sheets.find(s=>s.id===x.sheetId);if(!s)return '<p>Source unavailable.</p>';
 const cols=kind==='dataTables'?x.columns:x.columnIds.map(id=>s.columns.find(c=>c.id===id)).filter(Boolean),source=kind==='dataTables'?x.rows:viewRows(state,x),get=(r,c)=>kind==='dataTables'?r.cells[c.id]:val(s,r,c),policies=new Map();
 const visible=(r,c)=>{if(kind==='dataTables')return true;if(!policies.has(r.id))policies.set(r.id,fieldPolicy(state,x,r));return policies.get(r.id).get(c.id)?.visible;};
 const needle=prefs.query.toLowerCase(),rows=needle?source.filter(r=>cols.some(c=>visible(r,c)&&displayCell(get(r,c),c).toLowerCase().includes(needle))):source;
 prefs.page=Math.min(prefs.page,Math.max(0,Math.ceil(rows.length/50)-1));browserState.set(x.id,prefs);
 return `<section class="record-browser"><div class="record-browser-tools"><label class="hub-search">${icon('search',16)}<input data-record-search="${x.id}" aria-label="Search records" placeholder="Search visible fields…" value="${esc(prefs.query)}"></label><span>${fmt(rows.length)} matching records</span></div><div class="planning-scroll"><table class="workbench-table"><thead><tr>${cols.map(c=>`<th>${esc(c.name)}</th>`).join('')}${kind==='dynamicViews'?'<th>Details</th>':''}</tr></thead><tbody>${rows.slice(prefs.page*50,prefs.page*50+50).map(r=>`<tr>${cols.map(c=>`<td>${visible(r,c)?esc(displayCell(get(r,c),c)):'<span class="muted">Hidden by rule</span>'}</td>`).join('')}${kind==='dynamicViews'?`<td>${button('Open row','dynamic-row',`data-view="${x.id}" data-row="${r.id}"`)}</td>`:''}</tr>`).join('')}</tbody></table></div>${!rows.length?'<p class="quiet-empty">No records match this search or the configured row conditions.</p>':''}<div class="report-pagination">${button('Previous','records-page',`data-id="${x.id}" data-delta="-1" ${prefs.page===0?'disabled':''}`)}<span>${rows.length?prefs.page*50+1:0}–${Math.min((prefs.page+1)*50,rows.length)} of ${fmt(rows.length)}</span>${button('Next','records-page',`data-id="${x.id}" data-delta="1" ${(prefs.page+1)*50>=rows.length?'disabled':''}`)}</div></section>`;
}
Object.assign(actions,{
 'planning-select':el=>{planningSelection=el.dataset.id;render();},
 'portfolio-report':el=>{const x=state.portfolios.find(x=>x.id===el.dataset.id);transientReport={...defaultReport(),...x,id:'portfolio-report',name:x.name+' · source report',leafOnly:true,columns:['$task','$sheet','$status','$due','$cost'],statusColumn:'$status',dateColumn:'$due',sheetMappings:Object.fromEntries(x.sheetIds.map(id=>[id,{...inferSheetMappings(state.sheets.find(s=>s.id===id)),...x.sheetMappings?.[id]}]))};page='reports';render();},
 'records-page':el=>{const prefs=browserState.get(el.dataset.id);prefs.page=Math.max(0,prefs.page+Number(el.dataset.delta));render();},
 'scenario-clear':el=>modal('Clear scenario changes','<p>Remove all saved what-if cell changes from this scenario? Source sheet values remain unchanged.</p>',()=>mutate('Cleared scenario changes',n=>n.scenarios.find(x=>x.id===el.dataset.id).changes=[]),'Clear changes'),
 'scenario-bulk':el=>{const x=state.scenarios.find(x=>x.id===el.dataset.id),sources=state.sheets.filter(s=>x.sheetIds.includes(s.id));modal('Adjust scenario costs or dates',selectField('Source sheet','sheetId',sources.map(s=>({value:s.id,label:s.name})),sources[0]?.id),f=>{setTimeout(()=>bulkScenarioDialog(x,state.sheets.find(s=>s.id===f.sheetId)),0);return true;},'Choose adjustment');}
});
function bulkScenarioDialog(scenario,s){const cols=s.columns.filter(c=>!isReadOnly(c)&&['number','currency','percent','rating','duration','date','datetime'].includes(c.type));if(!cols.length)return toast('This sheet has no editable numeric or date columns.');modal('Adjust costs or dates',`<p>${esc(s.name)}</p>${selectField('Field','columnId',cols.map(c=>({value:c.id,label:c.name})),cols.find(c=>c.id===scenario.sheetMappings?.[s.id]?.costColumn)?.id||cols[0].id)}${selectField('Adjustment','mode',[{value:'percent',label:'Increase / decrease by percent'},{value:'add',label:'Add / subtract a fixed amount'},{value:'days',label:'Shift dates by calendar days'}],'percent')}${field('Amount (negative to decrease / move earlier)','amount',10,'number','step="any" required')}<p class="hint">Adjusts populated leaf cells. Parent rows, locked rows and formula cells are skipped. Repeated adjustments build on this scenario’s existing values.</p>`,f=>{const result=buildBulkChanges(state,scenario,{sheetId:s.id,...f});if(!result.changes.length)throw Error('No eligible cells would change.');setTimeout(()=>modal('Review scenario adjustment',`<p><b>${fmt(result.changes.length)} cells</b> will change in the scenario. ${fmt(result.skipped)} rows skipped.</p><div class="planning-scroll"><table class="workbench-table"><thead><tr><th>Item</th><th>Live value</th><th>Scenario value</th></tr></thead><tbody>${result.changes.slice(0,8).map(ch=>`<tr><td>${esc(title(s,s.rows.find(r=>r.id===ch.rowId)))}</td><td>${esc(ch.baseValue)}</td><td>${esc(ch.value)}</td></tr>`).join('')}</tbody></table></div><p class="hint">Previewing up to eight changes. Saving updates only the scenario.</p>`,()=>mutate('Adjusted scenario '+scenario.name,n=>{const x=n.scenarios.find(x=>x.id===scenario.id);x.changes=mergeScenarioChanges(x.changes||[],result.changes);}), 'Save scenario changes'),0);return true;},'Preview changes');}
document.addEventListener('input',e=>{if(e.target.dataset.recordSearch){const id=e.target.dataset.recordSearch,pos=e.target.selectionStart,prefs=browserState.get(id);prefs.query=e.target.value;prefs.page=0;render();const input=document.querySelector('[data-record-search="'+CSS.escape(id)+'"]');input.focus();input.setSelectionRange(pos,pos);}});

function reportPresets(){return currentSheets().map(s=>{const mapping=inferSheetMappings(s);return {...defaultReport(),id:'source-'+s.id,name:s.name+' · report',description:'Live source report. Configure to select fields, conditions, and groupings.',sheetIds:[s.id],columns:['$task',...(mapping.statusColumn?['$status']:[]),...(mapping.ownerColumn?['$owner']:[]),...(mapping.dueColumn?['$due']:[]),...(mapping.costColumn?['$cost']:[])],groupBy:'',sheetMappings:{[s.id]:mapping}};});}

actions['build-info']=()=>modal('Version & connection details',`<p><b>sheets v${esc(buildInfo.version)}</b><br>Build: <code>${esc(buildInfo.build)}</code></p><p>Connected to: <code>${esc(location.origin)}</code></p><p>Workspace: ${esc(state.workspaces.find(w=>w.id===workspaceId)?.name)}<br>${state.sheets.length} sheets · revision ${revision}</p><p class="hint">A localhost address connects to the machine running your browser unless a port-forwarding connection is configured. A cloud workspace and your own computer can serve different copies on the same port.</p>`,()=>true,'Done');

