 'row-options':el=>{const r=sheet().rows.find(r=>r.id===el.dataset.id);if(!selected.has(r.id))selected=new Set([r.id]);render();const item=(name,op,disabled=false)=>button(name,'row-operation',`data-id="${r.id}" data-operation="${op}" ${disabled?'disabled':''}`,'sheet-menu-item');modal('Row '+(sheet().rows.indexOf(r)+1)+' · '+title(sheet(),r),`<div class="row-action-list">${item('Insert row above','above')}${item('Insert row below','below')}${item('Make child of row above','indent',r.locked)}${item('Move out one level','outdent',r.locked)}${item(r.locked?'Unlock row':'Lock row','lock')}${item('Open row details','details')}${item('Delete selected rows','delete',r.locked)}</div>`,()=>true,'Done');},
