function budgetReview(){const s=sheet(),a=s.budgetAudit;if(!a)return;const filtered=a.issues.filter(x=>!budgetReviewKind||x.kind===budgetReviewKind),items=filtered.slice(budgetReviewPage*30,budgetReviewPage*30+30);modal('Budget import review',`<p><b>${fmt(a.rowCount)} source rows · ${fmt(a.formulaCount)} inferred formulas</b></p><p>${esc(a.method)}</p><p>Source errors: ${a.issues.filter(x=>x.kind==='Source error').length}. These values were already errors in the export. Unresolved values remain editable and unchanged.</p><details><summary>Calculation rules and input assumptions</summary>${Object.entries(a.formulaCounts).map(([k,v])=>`<p>${esc(k)}: ${fmt(v)}</p>`).join('')}<p>Quantity and unit rate are treated as inputs when their product matches cost. This inference cannot establish which field was the original Smartsheet input. Column labels are repurposed in some sections. No combined company budget is shown because projects, alternatives and subtotals would be counted more than once.</p></details><label class="field">Review category<select id="budget-review-kind">${option('','All issues',!budgetReviewKind)}${[...new Set(a.issues.map(x=>x.kind))].map(k=>option(k,k,k===budgetReviewKind)).join('')}</select></label><p>${fmt(filtered.length)} items · Source row numbers refer to Excel, including the header.</p>${items.map(x=>{const r=s.rows.find(r=>r.id===x.rowId),c=s.columns.find(c=>c.id===x.columnId);return `<article class="budget-review-item"><b>${esc(x.kind)} · Excel row ${x.sourceRow}</b><p>${esc(title(s,r))} — ${esc(c?.name)}</p><p>${esc(x.message)}</p>${button('Go to row','budget-review-row',`data-id="${x.rowId}"`)}</article>`;}).join('')}<div class="action-row">${button('Previous','budget-review-page',`data-delta="-1" ${budgetReviewPage===0?'disabled':''}`)}${button('Next','budget-review-page',`data-delta="1" ${(budgetReviewPage+1)*30>=filtered.length?'disabled':''}`)}${button('Download audit CSV','budget-review-export')}</div>`,()=>true,'Close');dialog.classList.add('column-inspector');}
Object.assign(actions,{'budget-review':()=>{budgetReviewPage=0;budgetReviewKind='';budgetReview();},'budget-review-page':el=>{budgetReviewPage+=Number(el.dataset.delta);budgetReview();},'budget-review-row':el=>{const s=sheet();query='';statusFilter='';collapsed.clear();localStorage.removeItem('sheets-filter-'+s.id);gridStart=Math.max(0,visibleRows(s).findIndex(r=>r.id===el.dataset.id)-40);gridKey=s.id+query+statusFilter+localStorage.getItem('sheets-filter-'+s.id);dialog.close();render();const td=document.querySelector(`[data-grid-row="${el.dataset.id}"]`);td?.scrollIntoView({block:'center'});td?.focus();},'budget-review-export':()=>{const s=sheet();download('budget-import-review.csv',[['Excel row','Description','Column','Issue','Explanation'],...s.budgetAudit.issues.map(x=>[x.sourceRow,title(s,s.rows.find(r=>r.id===x.rowId)),s.columns.find(c=>c.id===x.columnId)?.name,x.kind,x.message])].map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv');}});
