function queueHistory(direction){const task=editQueue.after(async()=>{if(conflictDraft)return toast('Resolve the workspace conflict first.');saving=true;$('#save-status')?.classList.add('busy');try{const usePatch=!editQueue.pending;const x=await request('/api/'+direction,{revision,respondWithPatch:usePatch});revision=x.revision;selected.clear();editQueue.replaceConfirmed(x.state||applyPatch(state,x.patch));restoreGridFocus();toast(direction==='undo'?'Change undone':'Change redone');}catch(e){toast(e.message);}finally{saving=false;$('#save-status')?.classList.remove('busy');}});return task;}
