document.addEventListener('keyup',e=>{if(e.target.matches('.cell-input')&&e.key==='F2')showInlineFormula(e.target);});
document.addEventListener('focusout',e=>{if(e.target.matches('.cell-input'))closeInlineFormula();});document.addEventListener('scroll',closeInlineFormula,true);

document.addEventListener('change',e=>{if(e.target.id!=='column-type'||!dialog.classList.contains('column-inspector'))return;const type=e.target.value,sections=typeSections(type);dialog.querySelectorAll('.column-section').forEach(el=>{el.hidden=!sections.has(el.dataset.section);});const hint=$('#column-type-hint');if(hint)hint.textContent=typeHints[type]||'';});

