for(const k of ['indent','outdent']){const base=actions[k];actions[k]=el=>{if(!selected.size){const r=selectedRange();if(r)selected=new Set(r.rows.map(x=>x.id));}if(!selected.size){toast('Select rows or cells to '+k+'.');return;}return base(el);};}

