 clearPickMarks();const target=document.querySelector(`td[data-grid-row="${CSS.escape(rows[cursor.ri].id)}"][data-grid-col="${CSS.escape(cols[cursor.ci].id)}"]`);target?.classList.add('formula-ref-pick');target?.scrollIntoView({block:'nearest',inline:'nearest'});
