// ---- Drag to reorder rows and columns ----
let gridDrag=null;
document.addEventListener('dragstart',e=>{const rowBtn=e.target.closest?.('.row-number-button'),colBtn=e.target.closest?.('th[data-grid-col] [data-action="select-column"]');if(!rowBtn&&!colBtn)return;e.stopPropagation();if(rowBtn){const id=rowBtn.dataset.id;gridDrag={kind:'row',ids:selected.has(id)?[...selected]:[id]};}else gridDrag={kind:'col',id:colBtn.dataset.id};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',gridDrag.kind==='row'?gridDrag.ids.length+' row(s)':'column');},true);
function clearDropMarks(){document.querySelectorAll('.drop-before').forEach(x=>x.classList.remove('drop-before'));}
document.addEventListener('dragover',e=>{if(!gridDrag)return;const tr=e.target.closest?.('table.grid tbody tr:not(.grid-spacer)'),th=e.target.closest?.('th[data-grid-col]');if(gridDrag.kind==='row'&&tr){e.preventDefault();clearDropMarks();tr.classList.add('drop-before');}if(gridDrag.kind==='col'&&th&&th.dataset.gridCol!==sheet().columns[0].id){e.preventDefault();clearDropMarks();th.classList.add('drop-before');}},true);
document.addEventListener('dragend',()=>{gridDrag=null;clearDropMarks();},true);
document.addEventListener('drop',e=>{if(!gridDrag)return;const drag=gridDrag;gridDrag=null;clearDropMarks();const s=sheet();if(drag.kind==='row'){const tr=e.target.closest?.('table.grid tbody tr:not(.grid-spacer)');const target=tr?.querySelector('td[data-grid-row]')?.dataset.gridRow;if(!target)return;e.preventDefault();e.stopPropagation();if(drag.ids.includes(target))return;const locked=drag.ids.filter(id=>s.rows.find(r=>r.id===id)?.locked);if(locked.length)return toast('Unlock the row before moving it.');let moved;try{moved=moveRows(s.rows,drag.ids,target);}catch(err){return toast(err.message);}mutate('Moved '+drag.ids.length+' row'+(drag.ids.length===1?'':'s'),n=>{const sh=n.sheets.find(x=>x.id===s.id),byId=new Map(sh.rows.map(r=>[r.id,r]));sh.rows=moved.map(r=>Object.assign(byId.get(r.id),{parentId:r.parentId??null}));}).catch(err=>toast(err.message));}
 else{const th=e.target.closest?.('th[data-grid-col]');if(!th)return;e.preventDefault();e.stopPropagation();const to=th.dataset.gridCol;if(to===drag.id||to===s.columns[0].id)return;mutate('Moved column',n=>{const sh=n.sheets.find(x=>x.id===s.id),from=sh.columns.findIndex(c=>c.id===drag.id),[col]=sh.columns.splice(from,1);sh.columns.splice(Math.max(1,sh.columns.findIndex(c=>c.id===to)),0,col);}).catch(err=>toast(err.message));}},true);

// ---- Find & replace ----
function frCells(scopeSelected){const s=sheet(),rows=visibleRows(s),range=rangeCells(),cols=scopeSelected&&range?range.columns:s.columns.filter(c=>!c.hidden),out=[];for(const r of rows)for(const c of cols)out.push({row:r.id,column:c.id,raw:r.cells[c.id]??'',shown:String(displayCell(val(s,r,c),c)??''),editable:!r.locked&&!isReadOnly(c)});return out;}
function frOptions(){const f=Object.fromEntries(new FormData($('#modal-form')));return {find:f.find||'',replace:f.replace??'',matchCase:!!f.matchCase,wholeCell:!!f.wholeCell,selected:!!f.selected};}
function updateFindCount(){const o=frOptions(),p=o.find?findReplacePlan(frCells(o.selected),{...o}):{matches:[],changes:[],skipped:0};const el=$('#fr-count');if(el)el.textContent=o.find?`${p.matches.length.toLocaleString()} match${p.matches.length===1?'':'es'} · ${p.changes.length.toLocaleString()} replaceable${p.skipped?` · ${p.skipped} skipped (formula, locked or read-only)`:''}`:'Type text to find.';}
actions['find-replace']=()=>{const range=rangeCells();modal('Find and replace',field('Find','find','','text','id="fr-find" autocomplete="off"')+field('Replace with','replace','','text','autocomplete="off"')+`<div class="fr-options"><label class="check-field"><input type="checkbox" name="matchCase">Match case</label><label class="check-field"><input type="checkbox" name="wholeCell">Entire cell only</label><label class="check-field"><input type="checkbox" name="selected" ${range&&range.columns.length<sheet().columns.filter(c=>!c.hidden).length?'':'disabled'}>Selected columns only</label></div><p class="hint" id="fr-count" aria-live="polite">Type text to find.</p><div class="action-row">${button('Find next','find-next')}</div><p class="hint">Formulas, locked rows and calculated columns are never changed. Replace all is one undo step.</p>`,async()=>{const o=frOptions();if(!o.find)throw Error('Enter text to find.');const s=sheet(),p=findReplacePlan(frCells(o.selected),o);if(!p.changes.length)throw Error('Nothing replaceable matches.');const cols=new Map(s.columns.map(c=>[c.id,c])),parsed=p.changes.map(ch=>{const c=cols.get(ch.column),v=parseCell(c,ch.value);validateCell(c,v);return {...ch,v};});const ok=await mutate(`Replaced ${parsed.length} cell${parsed.length===1?'':'s'}`,n=>{const sh=n.sheets.find(x=>x.id===s.id),byId=new Map(sh.rows.map(r=>[r.id,r]));for(const ch of parsed)byId.get(ch.row).cells[ch.column]=ch.v;});if(ok)toast(`Replaced ${parsed.length} cell${parsed.length===1?'':'s'}${p.skipped?` · ${p.skipped} skipped`:''}`);return ok;},'Replace all');$('#fr-find')?.focus();};
actions['find-next']=()=>{const o=frOptions();if(!o.find)return;const p=findReplacePlan(frCells(o.selected),{...o,replace:undefined});if(!p.matches.length)return toast('No matches.');const rows=visibleRows(sheet()),cols=sheet().columns.filter(c=>!c.hidden),key=m=>rows.findIndex(r=>r.id===m.row)*1000+cols.findIndex(c=>c.id===m.column),cur=activeCell?rows.findIndex(r=>r.id===activeCell.rowId)*1000+cols.findIndex(c=>c.id===activeCell.colId):-1,next=p.matches.find(m=>key(m)>cur)||p.matches[0];const ri=rows.findIndex(r=>r.id===next.row),ci=cols.findIndex(c=>c.id===next.column);moveGrid(ri,ci);const td=document.querySelector(`td[data-grid-row="${CSS.escape(next.row)}"][data-grid-col="${CSS.escape(next.column)}"]`);td?.scrollIntoView({block:'center'});$('#fr-find')?.focus();};
let frTimer;document.addEventListener('input',e=>{if(e.target.closest?.('#modal-form')&&$('#fr-count')){clearTimeout(frTimer);frTimer=setTimeout(updateFindCount,150);}});
document.addEventListener('change',e=>{if(e.target.closest?.('#modal-form')&&$('#fr-count'))updateFindCount();});
window.addEventListener('keydown',e=>{if(page!=='sheet'||dialog.open)return;const mod=e.metaKey||e.ctrlKey;if(mod&&e.shiftKey&&e.key.toLowerCase()==='h'){e.preventDefault();e.stopImmediatePropagation();actions['find-replace']();}},true);

// ---- Smartsheet migration (API token is sent per request and never stored) ----
let smartsheetList=[];
function ssListHTML(filter=''){const f=filter.toLowerCase(),items=smartsheetList.filter(x=>x.name.toLowerCase().includes(f));const imported=new Set(state.sheets.map(s=>String(s.source?.smartsheetId??'')));return items.length?items.map(x=>`<label class="check-field ss-item"><input type="checkbox" name="ss-${esc(x.id)}" ${imported.has(String(x.id))?'disabled':''}><span>${esc(x.name)}${imported.has(String(x.id))?' <small>(already imported)</small>':''}</span>${x.modifiedAt?`<small>${esc(new Date(x.modifiedAt).toLocaleDateString())}</small>`:''}</label>`).join(''):'<p class="hint">No sheets match.</p>';}
actions['smartsheet-import']=()=>{smartsheetList=[];modal('Import from Smartsheet',`<p class="hint">Brings sheets over with formulas, hierarchy, column types, comments, links, locks and formatting. Every imported formula is recalculated and compared with the value Smartsheet showed; differences are listed, never changed. Files attached in Smartsheet are not copied.</p>${selectField('Smartsheet region','region',[{value:'us',label:'United States (app.smartsheet.com)'},{value:'eu',label:'Europe (app.smartsheet.eu)'},{value:'au',label:'Australia (app.smartsheet.au)'}],'us')}<label class="field">API access token<input name="token" id="ss-token" type="password" autocomplete="off" spellcheck="false" placeholder="Smartsheet → Account → Apps & Integrations → API Access"></label><p class="hint">The token is used only for this import and is never saved.</p><div class="action-row">${button('Load my sheets','ss-load','','primary')}</div><div id="ss-picker" hidden><input id="ss-filter" placeholder="Filter sheets…" aria-label="Filter Smartsheet sheets"><div id="ss-list" class="ss-list"></div></div>`,async f=>{const ids=smartsheetList.filter(x=>f['ss-'+x.id]).map(x=>x.id);if(!ids.length)throw Error('Load your sheets and tick at least one.');toast('Importing '+ids.length+' sheet'+(ids.length===1?'':'s')+' from Smartsheet…');const x=await serverChange('/api/smartsheet/import',{token:f.token,region:f.region,sheetIds:ids});workspaceId=x.importedWorkspaceId;page='home';render();setTimeout(()=>smartsheetReport(x.report),0);return true;},'Import selected');};
actions['ss-load']=async()=>{const token=$('#ss-token')?.value,region=dialog.querySelector('[name="region"]')?.value;try{const r=await fetch('/api/smartsheet/sheets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,region})});const x=await r.json();if(!r.ok)throw Error(x.error);smartsheetList=x.sheets;$('#ss-picker').hidden=false;$('#ss-list').innerHTML=ssListHTML();toast(x.sheets.length+' sheets found');}catch(err){toast(err.message);}};
document.addEventListener('input',e=>{if(e.target.id==='ss-filter')$('#ss-list').innerHTML=ssListHTML(e.target.value);});
function smartsheetReport(report){const rows=report.sheets.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.rows.toLocaleString()}</td><td>${r.formulas.toLocaleString()}</td><td>${r.formulaMatches.toLocaleString()}</td><td>${(r.formulas-r.formulaMatches).toLocaleString()}</td><td>${r.comments}</td><td>${(r.attachmentsCopied||0).toLocaleString()}</td></tr>`).join('');const issues=report.sheets.flatMap(r=>[...r.formulaMismatches.map(m=>`<li>${esc(r.name)} · row ${m.row} · ${esc(m.column)}: Smartsheet showed <b>${esc(String(m.smartsheet??'blank'))}</b>, here <b>${esc(String(m.here??'blank'))}</b></li>`),...(r.typeFallbacks.length?[`<li>${esc(r.name)}: kept as text because some values did not fit their type: ${esc(r.typeFallbacks.join(', '))}</li>`]:[]),...(r.attachmentsNotCopied?[`<li>${esc(r.name)}: ${r.attachmentsNotCopied} attachment${r.attachmentsNotCopied===1?'':'s'} not copied${(r.attachmentsSkipped||[]).length?`<ul>${r.attachmentsSkipped.map(a=>`<li>${a.row!=null?'Row '+esc(String(a.row))+' · ':''}${esc(a.name)} — ${esc(a.reason)}</li>`).join('')}${r.attachmentsNotCopied>r.attachmentsSkipped.length?`<li>…and ${r.attachmentsNotCopied-r.attachmentsSkipped.length} more</li>`:''}</ul>`:''}</li>`]:[])]);modal('Smartsheet import report',`<table class="ss-report"><thead><tr><th>Sheet</th><th>Rows</th><th>Formulas</th><th>Match Smartsheet</th><th>Differ</th><th>Comments</th><th>Files copied</th></tr></thead><tbody>${rows}</tbody></table>${report.crossSheetUnresolved?`<p class="hint">${report.crossSheetUnresolved} cross-sheet reference(s) point at ranges or sheets that were not imported; they show #REF until the source sheet is imported.</p>`:''}${issues.length?`<h3>Review</h3><ul class="ss-issues">${issues.join('')}</ul>`:'<p><b>All imported formulas reproduce Smartsheet’s values.</b></p>'}${report.skipped?.length?`<p class="hint">Skipped (already imported): ${esc(report.skipped.join(', '))}</p>`:''}`,()=>true,'Done');dialog.classList.add('wide-dialog');}

// ---- Budget vs actual rollup across projects ----
function budgetRollupSection(metrics){const rows=metrics.filter(m=>m.budget!=null||m.actual!=null);if(!rows.length)return '';const money=v=>v==null?'—':new Intl.NumberFormat(undefined,{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);const tb=rows.reduce((n,m)=>n+(m.budget||0),0),ta=rows.reduce((n,m)=>n+(m.actual||0),0),both=rows.filter(m=>m.budget!=null&&m.actual!=null);
 return `<section class="budget-rollup"><div class="panel-heading"><div><h3>Budget vs actual</h3><p>${rows.length} project${rows.length===1?'':'s'} with mapped budget or actual. Sources are listed per project; check that projects do not overlap before relying on totals.</p></div></div>${budgetActualChart(rows,{format:money})}<table class="rollup-table"><thead><tr><th>Project</th><th>Budget</th><th>Actual</th><th>Variance</th><th>Used</th><th>Source</th></tr></thead><tbody>${rows.map(m=>`<tr class="${m.variance!=null&&m.variance<0?'over':''}"><td>${esc(m.name)}</td><td>${money(m.budget)}</td><td>${money(m.actual)}</td><td>${m.variance==null?'—':money(m.variance)+(m.variance<0?' over':'')}</td><td>${m.budget&&m.actual!=null?Math.round(m.actual/m.budget*100)+'%':'—'}</td><td class="muted">${esc([m.budgetSource,m.actualSource].filter(Boolean).join(' / '))}</td></tr>`).join('')}</tbody><tfoot><tr><th>Total</th><th>${money(tb)}</th><th>${money(ta)}</th><th>${both.length?money(both.reduce((n,m)=>n+m.variance,0)):'—'}</th><th>${tb&&both.length?Math.round(ta/tb*100)+'%':'—'}</th><th></th></tr></tfoot></table></section>`;}

// ---- Project templates ----
actions['toggle-folder-template']=el=>mutate('Updated template setting',n=>{const f=n.folders.find(x=>x.id===el.dataset.id);f.template=!f.template;}).then(ok=>{if(ok)toast(state.folders.find(x=>x.id===el.dataset.id)?.template?'Folder is now a project template':'Folder is no longer a template');});
actions['new-from-template']=()=>{const templates=state.folders.filter(f=>f.template&&state.sheets.some(s=>s.folderId===f.id));if(!templates.length)return modal('Project templates','<p>Make any folder a template: open its <b>Folder settings</b> and choose <b>Use as project template</b>. Every sheet in the folder (with formulas, rules, forms and the reports that use only those sheets) is copied into each new project.</p>',()=>true,'Got it');
 modal('New project from template',selectField('Template','folder',templates.map(f=>({value:f.id,label:`${f.name} (${state.sheets.filter(s=>s.folderId===f.id).length} sheets)`})),templates[0].id)+field('Project name','name','','text','required placeholder="e.g. Job 42 – Conroe Retail" autocomplete="off"')+selectField('What to copy','mode',Object.entries(PROJECT_MODES).map(([value,label])=>({value,label})),'clear')+'<p class="hint">Sheets are named “Project – Sheet”. References between template sheets point to the new copies; references to other sheets stay as they are. Comments, files, history and import audit data are not copied.</p>',f=>{const out=instantiateTemplate(state,{folderId:f.folder,projectName:f.name,mode:f.mode,workspaceId,makeId:uid});return mutate('Created project '+f.name.trim()+' from template',n=>{n.folders.push(out.folder);n.sheets.push(...out.sheets);n.reports.push(...out.reports);(n.dashboards||=[]).push(...out.dashboards);}).then(ok=>{if(ok){sheetId=out.sheets[0].id;page='sheet';render();toast(`Created ${out.sheets.length} sheet${out.sheets.length===1?'':'s'} for ${f.name.trim()}`);}return ok;});},'Create project');};

// Printing renders every row (the screen only keeps ~120 rows in the page), then restores the window.
{let saved=0;window.addEventListener('beforeprint',()=>{const s=sheet();if(!s||page!=='sheet'||view!=='Table'||!document.querySelector('table.grid tbody'))return;saved=gridStart;gridPrintAll=true;replaceGridBody(s,visibleRows(s));});
window.addEventListener('afterprint',()=>{if(!gridPrintAll)return;gridPrintAll=false;gridStart=saved;const s=sheet();if(s&&document.querySelector('table.grid tbody'))replaceGridBody(s,visibleRows(s));});}
